definition:
CREATE OR REPLACE FUNCTION public.approve_leave_request_by_supervisor(p_request_id uuid, p_supervisor_id uuid, p_supervisor_name text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_request leave_requests%rowtype;
  v_result text;
  v_locked boolean;
begin
  select *
  into v_request
  from leave_requests
  where id = p_request_id;

  if not found then
    raise exception 'Pengajuan tidak ditemukan.';
  end if;

  v_locked := is_employee_date_range_locked(
    v_request.employee_id,
    v_request.start_date::date,
    v_request.end_date::date
  );

  if v_locked then
    raise exception 'Periode pengajuan ini sudah dikunci HR. Buka lock terlebih dahulu jika perlu approval/revisi.';
  end if;

  if coalesce(v_request.supervisor_status, 'pending') = 'approved' then
    return 'Pengajuan ini sudah pernah disetujui atasan.';
  end if;

  if coalesce(v_request.request_type, '') = 'annual_leave' then
    v_result := use_employee_annual_leave_balance(
      v_request.employee_id,
      v_request.id,
      coalesce(v_request.total_days, 0),
      p_supervisor_name,
      'supervisor',
      'Saldo cuti tahunan dikurangi saat approval atasan.'
    );

    if v_result not ilike '%berhasil%'
       and v_result not ilike '%sudah pernah%' then
      raise exception '%', v_result;
    end if;
  end if;

  if coalesce(v_request.request_type, '') = 'phl_claim' then
    v_result := use_employee_phl_balance(
      v_request.employee_id,
      v_request.id,
      coalesce(v_request.total_days, 0),
      p_supervisor_name,
      'supervisor',
      'Saldo PHL dikurangi saat approval klaim PHL oleh atasan.'
    );

    if v_result not ilike '%berhasil%'
       and v_result not ilike '%sudah pernah%' then
      raise exception '%', v_result;
    end if;
  end if;

  update leave_requests
  set
    status = 'approved',
    supervisor_status = 'approved',
    supervisor_id = p_supervisor_id,
    supervisor_name = p_supervisor_name,
    supervisor_approved_at = now(),
    supervisor_rejected_at = null,
    supervisor_note = coalesce(p_note, 'Disetujui oleh atasan.'),
    updated_at = now()
  where id = p_request_id;

  return 'Pengajuan berhasil disetujui atasan.';
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_phl_claim(p_claim_record_id uuid, p_approved_by text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_claim record;
  v_requested_days numeric;
  v_available_days numeric;
  v_remaining_to_use numeric;
  v_take_days numeric;
  v_balance record;
begin
  select *
  into v_claim
  from phl_records
  where id = p_claim_record_id
  for update;

  if not found then
    return 'Klaim PHL tidak ditemukan.';
  end if;

  if coalesce(v_claim.source, '') <> 'employee_phl_claim' then
    return 'Record ini bukan pengajuan Klaim PHL.';
  end if;

  if coalesce(v_claim.status, '') = 'approved' then
    return 'Klaim PHL ini sudah pernah disetujui HR.';
  end if;

  if coalesce(v_claim.status, '') = 'rejected' then
    return 'Klaim PHL ini sudah ditolak.';
  end if;

  v_requested_days := coalesce(v_claim.used_days, 0);

  if v_requested_days <= 0 then
    return 'Jumlah hari klaim PHL tidak valid.';
  end if;

  select coalesce(sum(remaining_days), 0)
  into v_available_days
  from phl_records
  where employee_id = v_claim.employee_id
    and status = 'approved'
    and source = 'attendance_phl_approved'
    and coalesce(remaining_days, 0) > 0
    and (
      expired_at is null
      or expired_at::date >= current_date
    );

  if v_available_days < v_requested_days then
    return 'Saldo PHL tidak mencukupi.';
  end if;

  v_remaining_to_use := v_requested_days;

  for v_balance in
    select *
    from phl_records
    where employee_id = v_claim.employee_id
      and status = 'approved'
      and source = 'attendance_phl_approved'
      and coalesce(remaining_days, 0) > 0
      and (
        expired_at is null
        or expired_at::date >= current_date
      )
    order by expired_at asc nulls last, phl_date asc nulls last, created_at asc
    for update
  loop
    exit when v_remaining_to_use <= 0;

    v_take_days := least(coalesce(v_balance.remaining_days, 0), v_remaining_to_use);

    update phl_records
    set
      used_days = coalesce(used_days, 0) + v_take_days,
      remaining_days = greatest(coalesce(remaining_days, 0) - v_take_days, 0),
      updated_at = now()
    where id = v_balance.id;

    insert into phl_claim_usages (
      claim_record_id,
      balance_record_id,
      used_days,
      created_at
    )
    values (
      p_claim_record_id,
      v_balance.id,
      v_take_days,
      now()
    )
    on conflict (claim_record_id, balance_record_id)
    do update set
      used_days = phl_claim_usages.used_days + excluded.used_days;

    v_remaining_to_use := v_remaining_to_use - v_take_days;
  end loop;

  update phl_records
  set
    status = 'approved',
    hr_status = 'approved',
    hr_approved_by = p_approved_by,
    hr_approved_at = now(),
    approved_by = p_approved_by,
    approved_at = now(),
    notes = coalesce(notes, '') || E'\nKlaim PHL disetujui HR dan saldo PHL sudah dikurangi otomatis.',
    updated_at = now()
  where id = p_claim_record_id;

  return 'Klaim PHL berhasil disetujui HR dan saldo PHL berhasil dikurangi.';
end;
$function$

CREATE OR REPLACE FUNCTION public.harmony_attendance_is_phl_eligible(p_log attendance_logs)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_json jsonb := to_jsonb(p_log);
  v_date date;
  v_employee_id uuid;
  v_supervisor_status text;
  v_employee_status text;
  v_absence_type text;
  v_status text;
  v_check_in text;
  v_check_out text;
  v_is_weekend boolean := false;
  v_is_holiday boolean := false;
  v_period_approved boolean := false;
  v_work_like_request boolean := false;
  v_deleted boolean := false;
begin
  begin
    v_date := nullif(v_json ->> 'attendance_date', '')::date;
  exception when others then
    return false;
  end;

  begin
    v_employee_id := nullif(v_json ->> 'employee_id', '')::uuid;
  exception when others then
    return false;
  end;

  if v_date is null or v_employee_id is null then
    return false;
  end if;

  v_deleted := coalesce(nullif(v_json ->> 'deleted_at', ''), '') <> '';
  if v_deleted then
    return false;
  end if;

  v_supervisor_status := lower(btrim(coalesce(v_json ->> 'supervisor_approval_status', '')));
  v_employee_status := lower(btrim(coalesce(v_json ->> 'employee_confirmation_status', '')));

  if v_supervisor_status <> 'approved' then
    return false;
  end if;

  if v_employee_status <> 'submitted' then
    return false;
  end if;

  -- Effective pair: manual > requested > fingerprint/machine.
  v_check_in := coalesce(
    nullif(btrim(coalesce(v_json ->> 'manual_check_in', '')), ''),
    nullif(btrim(coalesce(v_json ->> 'requested_check_in', '')), ''),
    nullif(btrim(coalesce(v_json ->> 'check_in', '')), '')
  );

  v_check_out := coalesce(
    nullif(btrim(coalesce(v_json ->> 'manual_check_out', '')), ''),
    nullif(btrim(coalesce(v_json ->> 'requested_check_out', '')), ''),
    nullif(btrim(coalesce(v_json ->> 'check_out', '')), '')
  );

  if not public.harmony_attendance_value_present(v_check_in)
     or not public.harmony_attendance_value_present(v_check_out) then
    return false;
  end if;

  v_absence_type := lower(btrim(coalesce(v_json ->> 'absence_request_type', '')));
  v_status := lower(btrim(coalesce(v_json ->> 'status', '')));

  -- Request work-like tetap boleh menghasilkan PHL bila jam kerja lengkap.
  v_work_like_request := v_absence_type in (
    'official_travel', 'official_duty', 'business_trip', 'duty',
    'st', 'tugas_luar', 'dinas', 'luar_kota', 'field_work'
  );

  -- Bila ada request ketidakhadiran, selain work-like, jangan berikan PHL.
  if v_absence_type <> '' and not v_work_like_request then
    return false;
  end if;

  -- Safety jika request_type kosong tetapi status jelas ketidakhadiran.
  if v_status in (
    'absent', 'alpa', 'leave', 'annual_leave', 'sick', 'permit',
    'permission', 'phl', 'phl_claim', 'other_leave', 'special_leave'
  ) then
    return false;
  end if;

  v_is_weekend := extract(isodow from v_date)::int in (6, 7);

  select exists (
    select 1
    from public.holidays h
    where h.holiday_date::date = v_date
      and coalesce(h.is_active, true) = true
  )
  into v_is_holiday;

  if not (v_is_weekend or v_is_holiday) then
    return false;
  end if;

  -- Header periode juga wajib sudah approved supervisor.
  select exists (
    select 1
    from public.attendance_period_confirmations apc
    where apc.employee_id = v_employee_id
      and lower(coalesce(apc.employee_status, '')) = 'submitted'
      and lower(coalesce(apc.supervisor_status, '')) = 'approved'
      and v_date between apc.period_start::date and apc.period_end::date
  )
  into v_period_approved;

  return v_period_approved;
end;
$function$

CREATE OR REPLACE FUNCTION public.harmony_employee_cancel_leave_request_v1(p_request_id uuid, p_note text DEFAULT 'Dibatalkan oleh employee sebelum approval atasan.'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_employee_id uuid;
  v_request public.leave_requests%rowtype;
  v_supervisor_status text;
begin
  if auth.uid() is null then
    raise exception 'Session login tidak valid.';
  end if;

  v_employee_id := public.harmony_current_employee_id_v1();

  if v_employee_id is null then
    raise exception 'Akun belum terhubung ke employee aktif.';
  end if;

  if length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'Alasan pembatalan minimal 3 karakter.';
  end if;

  select *
  into v_request
  from public.leave_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'Pengajuan tidak ditemukan.';
  end if;

  if v_request.employee_id is distinct from v_employee_id then
    raise exception 'Pengajuan ini bukan milik employee yang sedang login.';
  end if;

  if lower(coalesce(v_request.request_type, '')) = 'phl_claim' then
    raise exception 'PHL claim harus dibatalkan melalui canonical phl_records.';
  end if;

  if lower(coalesce(v_request.status, '')) in ('cancelled', 'canceled') then
    return jsonb_build_object(
      'success', true,
      'already_cancelled', true,
      'request_id', v_request.id,
      'message', 'Pengajuan sebelumnya sudah dibatalkan.'
    );
  end if;

  v_supervisor_status := lower(btrim(coalesce(v_request.supervisor_status, '')));

  if v_supervisor_status in ('approved', 'rejected')
     or lower(btrim(coalesce(v_request.hr_status, ''))) in (
       'waiting_hr',
       'ready_for_hr',
       'approved',
       'finalized'
     ) then
    raise exception
      'Pengajuan sudah diproses atasan dan tidak dapat dibatalkan employee.';
  end if;

  if v_supervisor_status not in (
    '',
    'pending',
    'submitted',
    'waiting_supervisor',
    'pending_supervisor'
  ) then
    raise exception
      'Status pengajuan tidak lagi memenuhi syarat pembatalan employee.';
  end if;

  update public.leave_requests
  set
    status = 'cancelled',
    supervisor_status = 'cancelled',
    hr_status = 'cancelled',
    employee_cancelled_at = now(),
    employee_cancelled_by = auth.uid(),
    employee_cancel_note = btrim(p_note),
    updated_at = now()
  where id = v_request.id;

  return jsonb_build_object(
    'success', true,
    'request_id', v_request.id,
    'message', 'Pengajuan berhasil dibatalkan sebelum approval atasan.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.harmony_employee_cancel_phl_claim_v1(p_claim_record_id uuid, p_note text DEFAULT 'Dibatalkan oleh employee sebelum approval atasan.'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_employee_id uuid;
  v_claim public.phl_records%rowtype;
  v_supervisor_status text;
begin
  if auth.uid() is null then
    raise exception 'Session login tidak valid.';
  end if;

  v_employee_id := public.harmony_current_employee_id_v1();

  if v_employee_id is null then
    raise exception 'Akun belum terhubung ke employee aktif.';
  end if;

  if length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'Alasan pembatalan minimal 3 karakter.';
  end if;

  select *
  into v_claim
  from public.phl_records
  where id = p_claim_record_id
  for update;

  if not found then
    raise exception 'Klaim PHL tidak ditemukan.';
  end if;

  if v_claim.employee_id is distinct from v_employee_id then
    raise exception 'Klaim PHL ini bukan milik employee yang sedang login.';
  end if;

  if lower(coalesce(v_claim.source, '')) <> 'employee_phl_claim' then
    raise exception 'Record ini bukan canonical employee PHL claim.';
  end if;

  if lower(coalesce(v_claim.status, '')) in ('cancelled', 'canceled') then
    return jsonb_build_object(
      'success', true,
      'already_cancelled', true,
      'claim_record_id', v_claim.id,
      'message', 'Klaim PHL sebelumnya sudah dibatalkan.'
    );
  end if;

  v_supervisor_status := lower(btrim(coalesce(v_claim.supervisor_status, '')));

  if v_supervisor_status in ('approved', 'rejected')
     or lower(btrim(coalesce(v_claim.hr_status, ''))) in (
       'waiting_hr',
       'ready_for_hr',
       'approved',
       'finalized'
     ) then
    raise exception
      'Klaim PHL sudah diproses atasan dan tidak dapat dibatalkan employee.';
  end if;

  if v_supervisor_status not in (
    '',
    'pending',
    'submitted',
    'waiting_supervisor',
    'pending_supervisor'
  ) then
    raise exception
      'Status klaim PHL tidak lagi memenuhi syarat pembatalan employee.';
  end if;

  update public.phl_records
  set
    status = 'cancelled',
    supervisor_status = 'cancelled',
    hr_status = 'cancelled',
    employee_cancelled_at = now(),
    employee_cancelled_by = auth.uid(),
    employee_cancel_note = btrim(p_note),
    updated_at = now()
  where id = v_claim.id;

  return jsonb_build_object(
    'success', true,
    'claim_record_id', v_claim.id,
    'message', 'Klaim PHL berhasil dibatalkan sebelum approval atasan.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.harmony_employee_submit_phl_claim_v1(p_request_key uuid, p_claim_date date, p_days numeric, p_reason text, p_proof_file_url text DEFAULT NULL::text, p_proof_file_name text DEFAULT NULL::text, p_proof_file_size bigint DEFAULT NULL::bigint, p_proof_file_type text DEFAULT NULL::text, p_job_pending_summary text DEFAULT NULL::text, p_job_pending_detail text DEFAULT NULL::text, p_handover_to_employee_id uuid DEFAULT NULL::uuid, p_handover_to_employee_number text DEFAULT NULL::text, p_handover_to_full_name text DEFAULT NULL::text, p_handover_to_department text DEFAULT NULL::text, p_handover_to_position text DEFAULT NULL::text, p_handover_note text DEFAULT NULL::text, p_emergency_contact text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_employee_id uuid;
  v_employee public.employees%rowtype;
  v_actor_email text;
  v_available numeric := 0;
  v_claim_id uuid;
  v_existing public.phl_records%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Session login tidak ditemukan. Silakan login ulang.';
  end if;

  if p_request_key is null then
    raise exception 'Request key tidak tersedia.';
  end if;

  if p_claim_date is null then
    raise exception 'Tanggal klaim PHL wajib diisi.';
  end if;

  if coalesce(p_days,0) <> 1 then
    raise exception 'Klaim PHL saat ini wajib 1 hari kerja per pengajuan.';
  end if;

  if length(btrim(coalesce(p_reason,''))) < 3 then
    raise exception 'Alasan klaim PHL wajib diisi.';
  end if;

  if extract(isodow from p_claim_date) in (6,7)
     or exists (
       select 1
       from public.holidays h
       where public.harmony_safe_date(h.holiday_date::text)=p_claim_date
         and coalesce(h.is_active,true)=true
     ) then
    raise exception 'Klaim PHL hanya dapat digunakan pada hari kerja, bukan Sabtu/Minggu/libur aktif.';
  end if;

  if nullif(btrim(coalesce(p_job_pending_summary,'')),'') is null then
    raise exception 'Job pending wajib diisi.';
  end if;

  if nullif(btrim(coalesce(p_handover_to_full_name,'')),'') is null then
    raise exception 'Penerima handover/job pending wajib dipilih.';
  end if;

  v_employee_id := public.harmony_current_employee_id_v1();
  if v_employee_id is null then
    raise exception 'Akun belum terhubung ke data employee.';
  end if;

  select * into v_employee
  from public.employees
  where id=v_employee_id and coalesce(is_active,true)=true
  for update;

  if not found then
    raise exception 'Data employee aktif tidak ditemukan.';
  end if;

  v_actor_email := coalesce(nullif(lower(auth.jwt()->>'email'),''),nullif(lower(v_employee.email),''),'Employee');

  select * into v_existing
  from public.phl_records
  where request_key=p_request_key
  limit 1;

  if found then
    return jsonb_build_object(
      'success',true,
      'duplicate_request',true,
      'claim_record_id',v_existing.id,
      'message','Klaim PHL sebelumnya sudah tersimpan. Data tidak diduplikasi.'
    );
  end if;

  if exists (
    select 1 from public.phl_records pr
    where pr.employee_id=v_employee.id
      and lower(coalesce(pr.source,''))='employee_phl_claim'
      and pr.phl_date=p_claim_date
      and lower(coalesce(pr.status,'')) not in ('rejected','cancelled','canceled')
  ) then
    raise exception 'Sudah ada klaim PHL aktif pada tanggal tersebut.';
  end if;

  if to_regprocedure('public.is_employee_date_range_locked(uuid,date,date)') is not null then
    begin
      if public.is_employee_date_range_locked(v_employee.id,p_claim_date,p_claim_date) then
        raise exception 'Tanggal klaim masuk periode absensi yang sudah dikunci HR.';
      end if;
    exception when undefined_function then
      null;
    end;
  end if;

  v_available := public.harmony_phl_available_for_claim_v1(v_employee.id);
  if v_available + 0.0001 < p_days then
    raise exception 'Saldo PHL tidak cukup. Saldo aktif: % hari, kebutuhan: % hari.',v_available,p_days;
  end if;

  insert into public.phl_records (
    id,employee_id,employee_number,machine_pin,full_name,department,"position",email,
    phl_date,claim_start_date,claim_end_date,source,status,hr_status,
    balance_days,used_days,remaining_days,valid_from,expired_at,
    reason,notes,
    proof_file_url,proof_file_name,proof_file_size,proof_file_type,
    supervisor_status,supervisor_approved_by,supervisor_approved_at,
    supervisor_rejected_by,supervisor_rejected_at,supervisor_note,
    job_pending_summary,job_pending_detail,
    handover_to_employee_id,handover_to_employee_number,handover_to_full_name,
    handover_to_department,handover_to_position,handover_note,
    emergency_contact_during_leave,is_handover_required,handover_status,
    request_key,submitted_by,submitted_at,created_at,updated_at
  ) values (
    gen_random_uuid(),v_employee.id,v_employee.employee_number,v_employee.machine_pin,v_employee.full_name,v_employee.department,v_employee."position",v_employee.email,
    p_claim_date,p_claim_date,p_claim_date,'employee_phl_claim','pending','pending',
    p_days,p_days,0,p_claim_date,null,
    btrim(p_reason),'Klaim PHL diajukan employee dan menunggu approval atasan.',
    nullif(btrim(coalesce(p_proof_file_url,'')),''),nullif(btrim(coalesce(p_proof_file_name,'')),''),p_proof_file_size,nullif(btrim(coalesce(p_proof_file_type,'')),''),
    'pending',null,null,null,null,null,
    btrim(p_job_pending_summary),nullif(btrim(coalesce(p_job_pending_detail,'')),''),
    p_handover_to_employee_id,nullif(btrim(coalesce(p_handover_to_employee_number,'')),''),btrim(p_handover_to_full_name),
    nullif(btrim(coalesce(p_handover_to_department,'')),''),nullif(btrim(coalesce(p_handover_to_position,'')),''),nullif(btrim(coalesce(p_handover_note,'')),''),
    nullif(btrim(coalesce(p_emergency_contact,'')),''),true,'pending',
    p_request_key,v_actor_email,now(),now(),now()
  ) returning id into v_claim_id;

  return jsonb_build_object(
    'success',true,
    'claim_record_id',v_claim_id,
    'employee_id',v_employee.id,
    'phl_date',p_claim_date,
    'days',p_days,
    'available_balance',v_available,
    'message','Klaim PHL berhasil diajukan dan menunggu approval atasan.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.harmony_guard_phl_hr_decision_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_source text := lower(btrim(coalesce(new.source,'')));
  v_hr text := lower(btrim(coalesce(new.hr_status,'')));
  v_supervisor text := lower(btrim(coalesce(new.supervisor_status,'')));
  v_supervisor_approved boolean;
  v_supervisor_rejected boolean;
begin
  if v_source <> 'employee_phl_claim' then
    return new;
  end if;

  v_supervisor_approved := v_supervisor in (
    'approved','approve','approved_supervisor','disetujui'
  );

  v_supervisor_rejected := v_supervisor in (
    'rejected','reject','rejected_supervisor','rejected_by_supervisor','ditolak'
  );

  if v_hr = 'approved' and not v_supervisor_approved then
    raise exception 'Final approval HR PHL diblokir: approval atasan belum selesai.';
  end if;

  if v_hr = 'rejected'
     and not v_supervisor_approved
     and not v_supervisor_rejected then
    raise exception 'Penolakan HR PHL diblokir: klaim belum selesai diproses atasan.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.harmony_normalize_phl_claim_approval_state_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_source text := lower(btrim(coalesce(new.source,'')));
  v_supervisor text := lower(btrim(coalesce(new.supervisor_status,'')));
  v_hr text := lower(btrim(coalesce(new.hr_status,'')));
  v_status text := lower(btrim(coalesce(new.status,'')));
begin
  if v_source <> 'employee_phl_claim' then
    return new;
  end if;

  if v_hr in ('approved','finalized') then
    new.status := 'approved';
  elsif v_hr in ('rejected','rejected_by_hr') then
    new.status := 'rejected';
  elsif v_hr in ('cancelled','canceled') or v_status in ('cancelled','canceled') then
    new.status := 'cancelled';
  elsif v_supervisor in ('rejected','rejected_by_supervisor','rejected_supervisor') then
    new.status := 'rejected';
  elsif v_supervisor='approved'
        and v_hr in ('','pending','submitted','waiting_hr','ready_for_hr') then
    new.status := 'waiting_hr';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.harmony_period_phl_credit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.employee_id is null
     or new.period_start is null
     or new.period_end is null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    perform public.harmony_sync_phl_balance_from_attendance_v2(
      new.employee_id,
      new.period_start::date,
      new.period_end::date
    );
  elsif lower(coalesce(new.supervisor_status, '')) is distinct from lower(coalesce(old.supervisor_status, ''))
     or lower(coalesce(new.employee_status, '')) is distinct from lower(coalesce(old.employee_status, '')) then
    perform public.harmony_sync_phl_balance_from_attendance_v2(
      new.employee_id,
      new.period_start::date,
      new.period_end::date
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.harmony_phl_available_for_claim_v1(p_employee_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_balance numeric := 0;
begin
  if to_regprocedure('public.phl_get_effective_balance(uuid)') is not null then
    execute 'select public.phl_get_effective_balance($1)::numeric'
      into v_balance using p_employee_id;
    return greatest(coalesce(v_balance,0),0);
  end if;

  select greatest(coalesce(e.phl_balance,0),0)::numeric
  into v_balance
  from public.employees e
  where e.id=p_employee_id;

  return greatest(coalesce(v_balance,0),0);
end;
$function$

CREATE OR REPLACE FUNCTION public.harmony_phl_is_supervisor_of_v1(p_target_employee_id uuid, p_supervisor_employee_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_target public.employees%rowtype;
  v_supervisor public.employees%rowtype;
  v_s1 text;
  v_s2 text;
  v_options text[];
  v_homebase_match boolean := false;
  v_assignment_match boolean := false;
begin
  if p_target_employee_id is null or p_supervisor_employee_id is null then
    return false;
  end if;

  select *
  into v_target
  from public.employees
  where id = p_target_employee_id
    and coalesce(is_active, true) = true;

  if not found then
    return false;
  end if;

  select *
  into v_supervisor
  from public.employees
  where id = p_supervisor_employee_id
    and coalesce(is_active, true) = true;

  if not found then
    return false;
  end if;

  v_s1 := lower(btrim(coalesce(v_target.supervisor_1, '')));
  v_s2 := lower(btrim(coalesce(v_target.supervisor_2, '')));

  v_options := array[
    lower(btrim(coalesce(v_supervisor.id::text, ''))),
    lower(btrim(coalesce(v_supervisor.full_name, ''))),
    lower(btrim(coalesce(v_supervisor.employee_number, ''))),
    lower(btrim(coalesce(v_supervisor.machine_pin, ''))),
    lower(btrim(coalesce(v_supervisor.email, '')))
  ];

  v_homebase_match :=
       (v_s1 <> '' and v_s1 = any(v_options))
    or (v_s2 <> '' and v_s2 = any(v_options));

  select exists (
    select 1
    from public.employee_assignments ea
    where ea.employee_id = p_target_employee_id
      and coalesce(ea.is_active, true) = true
      and coalesce(ea.is_primary, false) = false
      and (ea.start_date is null or ea.start_date <= current_date)
      and (ea.end_date is null or ea.end_date >= current_date)
      and (
        (
          lower(btrim(coalesce(ea.supervisor_1, ''))) <> ''
          and lower(btrim(coalesce(ea.supervisor_1, ''))) = any(v_options)
        )
        or
        (
          lower(btrim(coalesce(ea.supervisor_2, ''))) <> ''
          and lower(btrim(coalesce(ea.supervisor_2, ''))) = any(v_options)
        )
      )
  )
  into v_assignment_match;

  return coalesce(v_homebase_match, false)
      or coalesce(v_assignment_match, false);
end;
$function$

CREATE OR REPLACE FUNCTION public.harmony_reconcile_attendance_period_v1(p_period_month text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_period_month text := btrim(coalesce(p_period_month, ''));
  v_start date;
  v_end date;
  v_row record;
  v_result jsonb;
  v_leave_employees integer := 0;
  v_leave_errors integer := 0;
  v_phl_claims integer := 0;
  v_phl_claim_errors integer := 0;
  v_phl_employee_sync integer := 0;
  v_phl_employee_errors integer := 0;
  v_actor_email text;
begin
  if not public.harmony_sync_is_hr_admin() then
    raise exception 'Hanya HR/Admin aktif yang dapat menjalankan reconciliation.';
  end if;

  if v_period_month !~ '^\\d{4}-(0[1-9]|1[0-2])$' then
    raise exception 'Format periode harus YYYY-MM, contoh 2026-07.';
  end if;

  v_start := to_date(v_period_month || '-11', 'YYYY-MM-DD');
  v_end := (v_start + interval '1 month' - interval '1 day')::date;

  select lower(coalesce(auth.jwt() ->> 'email', '')) into v_actor_email;
  if nullif(v_actor_email, '') is null then v_actor_email := 'HR Administrator'; end if;

  -- A. Reconcile source leave_requests per employee untuk seluruh periode.
  for v_row in
    select distinct lr.employee_id
    from public.leave_requests lr
    where lr.employee_id is not null
      and lr.start_date <= v_end
      and lr.end_date >= v_start
  loop
    begin
      perform public.sync_employee_absence_requests_to_attendance(
        v_row.employee_id,
        v_start,
        v_end
      );
      v_leave_employees := v_leave_employees + 1;
    exception when others then
      v_leave_errors := v_leave_errors + 1;
      insert into public.harmony_attendance_sync_audit_logs (
        period_month, period_start, period_end, employee_id,
        source_table, action, result_status, message, metadata,
        actor_user_id, actor_email
      ) values (
        v_period_month, v_start, v_end, v_row.employee_id,
        'leave_requests', 'period_leave_reconcile_failed', 'error', sqlerrm,
        '{}'::jsonb, auth.uid(), v_actor_email
      );
    end;
  end loop;

  -- B. Reconcile seluruh klaim PHL pada periode.
  for v_row in
    select pr.id
    from public.phl_records pr
    where lower(coalesce(pr.source, '')) = 'employee_phl_claim'
      and pr.phl_date between v_start and v_end
    order by pr.phl_date asc, pr.created_at asc nulls last, pr.id
  loop
    begin
      v_result := public.harmony_sync_phl_claim_to_attendance_v1(v_row.id);
      v_phl_claims := v_phl_claims + 1;
    exception when others then
      v_phl_claim_errors := v_phl_claim_errors + 1;
      insert into public.harmony_attendance_sync_audit_logs (
        period_month, period_start, period_end,
        source_table, source_id, action, result_status, message,
        actor_user_id, actor_email
      ) values (
        v_period_month, v_start, v_end,
        'phl_records', v_row.id, 'period_phl_claim_reconcile_failed', 'error', sqlerrm,
        auth.uid(), v_actor_email
      );
    end;
  end loop;

  -- C. Bila Auto-PHL V5.2 tersedia, reconcile entitlement kerja hari libur juga.
  if to_regprocedure('public.harmony_sync_phl_balance_from_attendance_v2(uuid,date,date)') is not null then
    for v_row in
      select distinct employee_id
      from (
        select al.employee_id
        from public.attendance_logs al
        where al.employee_id is not null
          and al.attendance_date::date between v_start and v_end
          and al.deleted_at is null
        union
        select apc.employee_id
        from public.attendance_period_confirmations apc
        where apc.employee_id is not null
          and apc.period_start::date <= v_end
          and apc.period_end::date >= v_start
      ) src
    loop
      begin
        execute 'select public.harmony_sync_phl_balance_from_attendance_v2($1,$2,$3)'
          into v_result
          using v_row.employee_id, v_start, v_end;
        v_phl_employee_sync := v_phl_employee_sync + 1;
      exception when others then
        v_phl_employee_errors := v_phl_employee_errors + 1;
        insert into public.harmony_attendance_sync_audit_logs (
          period_month, period_start, period_end, employee_id,
          source_table, action, result_status, message,
          actor_user_id, actor_email
        ) values (
          v_period_month, v_start, v_end, v_row.employee_id,
          'attendance_logs', 'period_auto_phl_reconcile_failed', 'error', sqlerrm,
          auth.uid(), v_actor_email
        );
      end;
    end loop;
  end if;

  insert into public.harmony_attendance_sync_audit_logs (
    period_month, period_start, period_end,
    source_table, action, result_status, message, metadata,
    actor_user_id, actor_email
  ) values (
    v_period_month, v_start, v_end,
    'period', 'period_reconciliation',
    case when (v_leave_errors + v_phl_claim_errors + v_phl_employee_errors) = 0 then 'success' else 'warning' end,
    'Reconciliation periode selesai.',
    jsonb_build_object(
      'leave_employees_processed', v_leave_employees,
      'leave_errors', v_leave_errors,
      'phl_claims_processed', v_phl_claims,
      'phl_claim_errors', v_phl_claim_errors,
      'auto_phl_employees_processed', v_phl_employee_sync,
      'auto_phl_errors', v_phl_employee_errors,
      'auto_phl_v5_2_available', to_regprocedure('public.harmony_sync_phl_balance_from_attendance_v2(uuid,date,date)') is not null
    ),
    auth.uid(), v_actor_email
  );

  return jsonb_build_object(
    'success', (v_leave_errors + v_phl_claim_errors + v_phl_employee_errors) = 0,
    'period_month', v_period_month,
    'period_start', v_start,
    'period_end', v_end,
    'leave_employees_processed', v_leave_employees,
    'leave_errors', v_leave_errors,
    'phl_claims_processed', v_phl_claims,
    'phl_claim_errors', v_phl_claim_errors,
    'auto_phl_employees_processed', v_phl_employee_sync,
    'auto_phl_errors', v_phl_employee_errors,
    'auto_phl_v5_2_available', to_regprocedure('public.harmony_sync_phl_balance_from_attendance_v2(uuid,date,date)') is not null,
    'message', case
      when (v_leave_errors + v_phl_claim_errors + v_phl_employee_errors) = 0
        then 'Reconciliation selesai tanpa error. Normal workflow tetap auto-sync; tombol ini hanya recovery.'
      else 'Reconciliation selesai dengan warning. Lihat harmony_attendance_sync_audit_logs untuk detail error.'
    end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.harmony_supervisor_review_phl_claim_v1(p_claim_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_supervisor_id uuid;
  v_supervisor public.employees%rowtype;
  v_claim public.phl_records%rowtype;
  v_action text := lower(btrim(coalesce(p_action,'')));
  v_name text;
begin
  if auth.uid() is null then
    raise exception 'Session login tidak ditemukan.';
  end if;

  if v_action not in ('approve','reject') then
    raise exception 'Action hanya boleh approve atau reject.';
  end if;

  if v_action='reject' and length(btrim(coalesce(p_note,''))) < 3 then
    raise exception 'Alasan reject wajib diisi.';
  end if;

  v_supervisor_id := public.harmony_current_employee_id_v1();
  if v_supervisor_id is null then
    raise exception 'Akun atasan belum terhubung ke data employee.';
  end if;

  select * into v_supervisor from public.employees where id=v_supervisor_id;
  v_name := coalesce(nullif(v_supervisor.full_name,''),nullif(v_supervisor.email,''),'Supervisor');

  select * into v_claim
  from public.phl_records
  where id=p_claim_id
  for update;

  if not found then raise exception 'Klaim PHL tidak ditemukan.'; end if;
  if lower(coalesce(v_claim.source,'')) <> 'employee_phl_claim' then
    raise exception 'Record ini bukan klaim PHL employee.';
  end if;

  if not public.harmony_phl_is_supervisor_of_v1(v_claim.employee_id,v_supervisor_id) then
    raise exception 'Anda bukan atasan yang berhak memproses klaim PHL ini.';
  end if;

  if lower(coalesce(v_claim.hr_status,''))='approved' or lower(coalesce(v_claim.status,''))='approved' then
    raise exception 'Klaim sudah final approved HR dan tidak dapat diubah dari approval atasan.';
  end if;

  if v_action='approve' then
    update public.phl_records
    set
      status='waiting_hr',
      supervisor_status='approved',
      supervisor_approved_by=v_name,
      supervisor_approved_at=now(),
      supervisor_rejected_by=null,
      supervisor_rejected_at=null,
      supervisor_note=coalesce(nullif(btrim(coalesce(p_note,'')),''),'Disetujui oleh atasan.'),
      hr_status='pending',
      updated_at=now()
    where id=v_claim.id;

    return jsonb_build_object('success',true,'claim_record_id',v_claim.id,'status','waiting_hr','message','Klaim PHL disetujui atasan dan diteruskan ke HR.');
  end if;

  update public.phl_records
  set
    status='rejected',
    supervisor_status='rejected',
    supervisor_rejected_by=v_name,
    supervisor_rejected_at=now(),
    supervisor_approved_by=null,
    supervisor_approved_at=null,
    supervisor_note=btrim(p_note),
    hr_status='rejected',
    updated_at=now()
  where id=v_claim.id;

  return jsonb_build_object('success',true,'claim_record_id',v_claim.id,'status','rejected','message','Klaim PHL ditolak atasan.');
end;
$function$

CREATE OR REPLACE FUNCTION public.harmony_sync_phl_balance_from_attendance_v2(p_employee_id uuid, p_period_start date, p_period_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_log record;
  v_result jsonb;
  v_processed integer := 0;
  v_credited integer := 0;
  v_reversed integer := 0;
  v_restored integer := 0;
  v_balance numeric(10,2) := 0;
begin
  if p_employee_id is null then
    raise exception 'Employee ID tidak tersedia untuk sinkronisasi PHL.';
  end if;

  if p_period_start is null or p_period_end is null or p_period_start > p_period_end then
    raise exception 'Rentang periode sinkronisasi PHL tidak valid.';
  end if;

  for v_log in
    select al.id
    from public.attendance_logs al
    where al.employee_id = p_employee_id
      and al.attendance_date::date between p_period_start and p_period_end
    order by al.attendance_date asc, al.created_at asc nulls last, al.id
  loop
    v_result := public.harmony_reconcile_phl_credit_for_attendance(v_log.id);
    v_processed := v_processed + 1;

    case coalesce(v_result ->> 'action', '')
      when 'credited' then v_credited := v_credited + 1;
      when 'reversed' then v_reversed := v_reversed + 1;
      when 'restored' then v_restored := v_restored + 1;
      else null;
    end case;
  end loop;

  v_balance := public.phl_sync_employee_effective_balance(p_employee_id);

  return jsonb_build_object(
    'success', true,
    'employee_id', p_employee_id,
    'period_start', p_period_start,
    'period_end', p_period_end,
    'processed_logs', v_processed,
    'credited', v_credited,
    'reversed', v_reversed,
    'restored', v_restored,
    'effective_phl_balance', v_balance,
    'message', 'Sinkronisasi PHL dari attendance selesai.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.hr_adjust_employee_phl_balance_with_evidence_v1(p_request_key uuid, p_employee_id uuid, p_action text, p_days numeric, p_phl_date date DEFAULT NULL::date, p_description text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_actor_email text DEFAULT NULL::text, p_evidence jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
  v_adjustment_id uuid;
  v_owner_employee_id uuid;
  v_evidence jsonb := coalesce(p_evidence, '[]'::jsonb);
  v_item jsonb;
  v_slot integer;
  v_file_url text;
  v_file_name text;
  v_file_size bigint;
  v_file_type text;
  v_storage_bucket text;
  v_storage_path text;
  v_attachment_kind text;
  v_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Sesi login tidak ditemukan. Silakan login ulang.';
  end if;

  if not public.harmony_is_active_hr_admin() then
    raise exception 'Hanya akun HR/Admin aktif yang dapat menyesuaikan saldo PHL.';
  end if;

  if jsonb_typeof(v_evidence) <> 'array' then
    raise exception 'Format evidence penyesuaian PHL tidak valid.';
  end if;

  v_count := jsonb_array_length(v_evidence);

  if v_count < 1 then
    raise exception 'Minimal 1 file evidence wajib dilampirkan untuk penyesuaian PHL manual HR.';
  end if;

  if v_count > 3 then
    raise exception 'Maksimal 3 file evidence untuk satu penyesuaian PHL manual HR.';
  end if;

  -- Canonical engine existing. Tidak ditulis ulang.
  v_result := public.hr_adjust_employee_phl_balance_v2(
    p_request_key,
    p_employee_id,
    p_action,
    p_days,
    p_phl_date,
    p_description,
    p_reason,
    p_actor_email
  );

  if lower(coalesce(v_result ->> 'success', 'false')) <> 'true' then
    raise exception '%', coalesce(v_result ->> 'message', 'Penyesuaian saldo PHL gagal diproses.');
  end if;

  v_adjustment_id := nullif(v_result ->> 'adjustment_id', '')::uuid;

  if v_adjustment_id is null then
    raise exception 'Adjustment ID tidak tersedia dari engine PHL.';
  end if;

  select a.employee_id
  into v_owner_employee_id
  from public.phl_hr_adjustments a
  where a.id = v_adjustment_id
  limit 1;

  if v_owner_employee_id is null then
    raise exception 'Data adjustment PHL tidak ditemukan setelah engine diproses.';
  end if;

  for v_item in
    select value
    from jsonb_array_elements(v_evidence)
  loop
    v_slot := nullif(v_item ->> 'slot_no', '')::integer;
    v_file_url := btrim(coalesce(v_item ->> 'file_url', ''));
    v_file_name := btrim(coalesce(v_item ->> 'file_name', ''));
    v_file_size := nullif(v_item ->> 'file_size', '')::bigint;
    v_file_type := nullif(btrim(coalesce(v_item ->> 'file_type', '')), '');
    v_storage_bucket := coalesce(nullif(btrim(coalesce(v_item ->> 'storage_bucket', '')), ''), 'leave-attachments');
    v_storage_path := nullif(btrim(coalesce(v_item ->> 'storage_path', '')), '');
    v_attachment_kind := coalesce(
      nullif(btrim(coalesce(v_item ->> 'attachment_kind', '')), ''),
      'hr_phl_manual_evidence'
    );

    if v_slot is null or v_slot < 1 or v_slot > 3 then
      raise exception 'Slot evidence PHL harus berada pada 1 sampai 3.';
    end if;

    if v_file_url = '' or v_file_name = '' then
      raise exception 'Metadata file evidence PHL belum lengkap.';
    end if;

    if v_storage_bucket <> 'leave-attachments' then
      raise exception 'Storage bucket evidence PHL tidak valid.';
    end if;

    insert into public.harmony_request_attachments (
      entity_type,
      entity_id,
      owner_employee_id,
      slot_no,
      attachment_kind,
      file_url,
      file_name,
      file_size,
      file_type,
      storage_bucket,
      storage_path,
      is_legacy,
      created_by_user_id,
      created_at
    )
    values (
      'phl_adjustment',
      v_adjustment_id,
      v_owner_employee_id,
      v_slot,
      v_attachment_kind,
      v_file_url,
      v_file_name,
      v_file_size,
      v_file_type,
      v_storage_bucket,
      v_storage_path,
      false,
      auth.uid(),
      now()
    )
    on conflict (entity_type, entity_id, slot_no) do nothing;
  end loop;

  select count(*)::integer
  into v_count
  from public.harmony_request_attachments a
  where a.entity_type = 'phl_adjustment'
    and a.entity_id = v_adjustment_id;

  return v_result || jsonb_build_object(
    'evidence_count', v_count,
    'evidence_required', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.hr_approve_leave_request_atomic(p_request_id uuid, p_approved_by text DEFAULT NULL::text, p_note text DEFAULT 'Disetujui oleh HR.'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_request public.leave_requests%rowtype;
  v_employee public.employees%rowtype;
  v_actor_role text;
  v_actor_email text;
  v_approved_by text;
  v_request_type text;
  v_days numeric(10, 2);
  v_balance_field text := null;
  v_balance_before numeric(10, 2) := null;
  v_balance_after numeric(10, 2) := null;
begin
  -- Pastikan pemanggil adalah HR/Admin aktif.
  select
    lower(coalesce(au.role, '')),
    lower(coalesce(au.email, ''))
  into
    v_actor_role,
    v_actor_email
  from public.app_users au
  where au.id = auth.uid()
    and coalesce(au.is_active, true) = true
  limit 1;

  if auth.uid() is null then
    raise exception 'Sesi login tidak ditemukan. Silakan login ulang.';
  end if;

  if not (
    coalesce(v_actor_role, '') like '%hr%'
    or coalesce(v_actor_role, '') like '%admin%'
  ) then
    raise exception 'Hanya akun HR/Admin aktif yang dapat melakukan approval final.';
  end if;

  v_approved_by := coalesce(
    nullif(btrim(coalesce(p_approved_by, '')), ''),
    nullif(v_actor_email, ''),
    'HR Administrator'
  );

  -- Kunci row pengajuan agar tidak diproses bersamaan.
  select *
  into v_request
  from public.leave_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'Pengajuan cuti/izin tidak ditemukan.';
  end if;

  -- Idempotent: klik ulang tidak akan memotong saldo dua kali.
  if lower(coalesce(v_request.hr_status, '')) = 'approved'
     or lower(coalesce(v_request.status, '')) = 'approved' then
    return jsonb_build_object(
      'success', true,
      'already_approved', true,
      'request_id', v_request.id,
      'employee_id', v_request.employee_id,
      'message', 'Pengajuan sebelumnya sudah disetujui HR. Saldo tidak dipotong ulang.'
    );
  end if;

  if lower(coalesce(v_request.hr_status, '')) = 'rejected'
     or lower(coalesce(v_request.status, '')) = 'rejected' then
    raise exception 'Pengajuan sudah ditolak dan tidak dapat di-approve langsung.';
  end if;

  if lower(coalesce(v_request.supervisor_status, '')) not in (
    'approved',
    'approve',
    'approved_supervisor',
    'disetujui'
  ) then
    raise exception 'Approval atasan belum selesai. HR belum dapat melakukan final approval.';
  end if;

  if v_request.employee_id is null then
    raise exception 'Pengajuan belum terhubung ke data employee.';
  end if;

  if v_request.start_date is null or v_request.end_date is null then
    raise exception 'Tanggal mulai atau tanggal selesai pengajuan belum lengkap.';
  end if;

  if v_request.end_date < v_request.start_date then
    raise exception 'Rentang tanggal pengajuan tidak valid.';
  end if;

  v_days := greatest(coalesce(v_request.total_days, 0), 0);

  if v_days <= 0 then
    raise exception 'Total hari pengajuan harus lebih dari 0.';
  end if;

  -- Jangan mengubah pengajuan yang sudah masuk periode terkunci.
  if exists (
    select 1
    from public.attendance_period_confirmations apc
    where apc.employee_id = v_request.employee_id
      and coalesce(apc.is_locked, false) = true
      and apc.period_start <= v_request.end_date
      and apc.period_end >= v_request.start_date
  ) then
    raise exception 'Periode absensi terkait sudah dikunci HR. Buka lock terlebih dahulu.';
  end if;

  if exists (
    select 1
    from public.attendance_logs al
    where al.employee_id = v_request.employee_id
      and public.harmony_safe_date(al.attendance_date::text) between v_request.start_date and v_request.end_date
      and coalesce(al.is_locked, false) = true
      and al.deleted_at is null
  ) then
    raise exception 'Salah satu tanggal absensi terkait sudah dikunci HR. Buka lock terlebih dahulu.';
  end if;

  -- Kunci employee agar saldo tidak dipotong oleh dua request bersamaan.
  select *
  into v_employee
  from public.employees
  where id = v_request.employee_id
  for update;

  if not found then
    raise exception 'Data employee untuk pengajuan ini tidak ditemukan.';
  end if;

  v_request_type := lower(btrim(coalesce(v_request.request_type, '')));

  -- Saldo manual HR hanya dipotong bila kolom override memang terisi.
  -- Bila NULL, sistem tetap memakai perhitungan summary/cycle yang sudah ada.
  if v_request_type = 'annual_leave' then
    if v_employee.annual_leave_balance is not null then
      v_balance_field := 'annual_leave_balance';
      v_balance_before := v_employee.annual_leave_balance;

      if v_balance_before < v_days then
        raise exception
          'Saldo cuti tahunan tidak cukup. Saldo tersedia: % hari, kebutuhan: % hari.',
          v_balance_before,
          v_days;
      end if;

      v_balance_after := v_balance_before - v_days;

      update public.employees
      set
        annual_leave_balance = v_balance_after,
        updated_at = now()
      where id = v_employee.id;
    end if;

  elsif v_request_type = 'phl_claim' then
    if v_employee.phl_balance is not null then
      v_balance_field := 'phl_balance';
      v_balance_before := v_employee.phl_balance;

      if v_balance_before < v_days then
        raise exception
          'Saldo PHL tidak cukup. Saldo tersedia: % hari, kebutuhan: % hari.',
          v_balance_before,
          v_days;
      end if;

      v_balance_after := v_balance_before - v_days;

      update public.employees
      set
        phl_balance = v_balance_after,
        updated_at = now()
      where id = v_employee.id;
    end if;
  end if;

  -- Final approval.
  update public.leave_requests
  set
    status = 'approved',
    hr_status = 'approved',
    hr_approved_by = v_approved_by,
    hr_approved_at = now(),
    hr_note = coalesce(
      nullif(btrim(coalesce(p_note, '')), ''),
      'Disetujui oleh HR.'
    ),
    updated_at = now()
  where id = v_request.id;

  -- Sinkronisasi ke absensi berada dalam transaksi yang sama.
  -- Bila RPC ini gagal/tidak tersedia, approval dan pemotongan saldo rollback.
  perform public.sync_employee_absence_requests_to_attendance(
    v_request.employee_id,
    v_request.start_date,
    v_request.end_date
  );

  insert into public.leave_balance_audit_logs (
    request_id,
    employee_id,
    request_type,
    leave_type,
    total_days,
    balance_field,
    balance_before,
    balance_after,
    action,
    actor_user_id,
    actor_email,
    note,
    metadata
  )
  values (
    v_request.id,
    v_request.employee_id,
    v_request.request_type,
    v_request.leave_type,
    v_days,
    v_balance_field,
    v_balance_before,
    v_balance_after,
    'hr_approved',
    auth.uid(),
    v_approved_by,
    coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'Disetujui oleh HR.'),
    jsonb_build_object(
      'period_start', v_request.start_date,
      'period_end', v_request.end_date,
      'supervisor_status', v_request.supervisor_status,
      'attendance_sync', 'success',
      'manual_balance_override_used', v_balance_field is not null
    )
  );

  return jsonb_build_object(
    'success', true,
    'already_approved', false,
    'request_id', v_request.id,
    'employee_id', v_request.employee_id,
    'request_type', v_request.request_type,
    'total_days', v_days,
    'balance_field', v_balance_field,
    'balance_before', v_balance_before,
    'balance_after', v_balance_after,
    'attendance_sync', 'success',
    'message', 'Pengajuan berhasil disetujui HR, saldo diperbarui, dan absensi tersinkron.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.hr_approve_phl_claim_atomic(p_claim_record_id uuid, p_approved_by text DEFAULT NULL::text, p_note text DEFAULT 'Disetujui oleh HR.'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_claim_before public.phl_records%rowtype;
  v_claim_after public.phl_records%rowtype;
  v_employee public.employees%rowtype;

  v_actor_role text;
  v_actor_email text;
  v_approved_by text;
  v_approval_note text;
  v_legacy_message text;

  v_claim_days numeric(10, 2) := 0;
  v_available_before numeric(10, 2) := 0;
  v_available_after numeric(10, 2) := 0;
  v_override_before numeric(10, 2) := null;
  v_override_after numeric(10, 2) := null;
  v_override_consumed numeric(10, 2) := 0;

  v_source_snapshot jsonb := '[]'::jsonb;
  v_snapshot_item jsonb;
  v_source_id uuid;
  v_source_balance numeric(10, 2);
  v_source_used_before numeric(10, 2);
  v_source_used_after numeric(10, 2);
  v_source_remaining_before numeric(10, 2);
  v_source_remaining_after numeric(10, 2);
  v_source_valid_from date;
  v_source_expired_at date;
  v_consumed numeric(10, 2);
  v_allocated_total numeric(10, 2) := 0;
  v_allocation_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Sesi login tidak ditemukan. Silakan login ulang.';
  end if;

  select
    lower(coalesce(au.role, '')),
    lower(coalesce(au.email, ''))
  into
    v_actor_role,
    v_actor_email
  from public.app_users au
  where au.id = auth.uid()
    and coalesce(au.is_active, true) = true
  limit 1;

  if not (
    coalesce(v_actor_role, '') like '%hr%'
    or coalesce(v_actor_role, '') like '%admin%'
  ) then
    raise exception 'Hanya akun HR/Admin aktif yang dapat menyetujui klaim PHL.';
  end if;

  v_approved_by := coalesce(
    nullif(btrim(coalesce(p_approved_by, '')), ''),
    nullif(v_actor_email, ''),
    'HR Administrator'
  );

  v_approval_note := coalesce(
    nullif(btrim(coalesce(p_note, '')), ''),
    'Disetujui oleh HR.'
  );

  select *
  into v_claim_before
  from public.phl_records
  where id = p_claim_record_id
  for update;

  if not found then
    raise exception 'Data klaim PHL tidak ditemukan.';
  end if;

  if lower(coalesce(v_claim_before.source, '')) <> 'employee_phl_claim' then
    raise exception 'Record ini bukan klaim PHL karyawan.';
  end if;

  if lower(coalesce(v_claim_before.status, '')) = 'approved'
     or lower(coalesce(v_claim_before.hr_status, '')) = 'approved' then
    return jsonb_build_object(
      'success', true,
      'already_approved', true,
      'claim_record_id', v_claim_before.id,
      'employee_id', v_claim_before.employee_id,
      'message', 'Klaim PHL sebelumnya sudah disetujui. Saldo tidak dipotong ulang.'
    );
  end if;

  if lower(coalesce(v_claim_before.status, '')) in ('rejected', 'cancelled', 'canceled')
     or lower(coalesce(v_claim_before.hr_status, '')) in ('rejected', 'cancelled', 'canceled') then
    raise exception 'Klaim PHL sudah ditolak atau dibatalkan dan tidak dapat langsung disetujui.';
  end if;

  if lower(coalesce(v_claim_before.supervisor_status, '')) = 'rejected' then
    raise exception 'Klaim PHL sudah ditolak atasan.';
  end if;

  if v_claim_before.employee_id is null then
    raise exception 'Klaim PHL belum terhubung ke data employee.';
  end if;

  if v_claim_before.phl_date is null then
    raise exception 'Tanggal klaim PHL belum tersedia.';
  end if;

  v_claim_days := coalesce(
    nullif(v_claim_before.used_days, 0),
    nullif(v_claim_before.balance_days, 0),
    0
  );

  if v_claim_days <= 0 then
    raise exception 'Jumlah hari klaim PHL harus lebih dari 0.';
  end if;

  if exists (
    select 1
    from public.attendance_period_confirmations apc
    where apc.employee_id = v_claim_before.employee_id
      and coalesce(apc.is_locked, false) = true
      and apc.period_start <= v_claim_before.phl_date
      and apc.period_end >= v_claim_before.phl_date
  ) then
    raise exception 'Periode absensi tanggal klaim sudah dikunci HR. Buka lock terlebih dahulu.';
  end if;

  if exists (
    select 1
    from public.attendance_logs al
    where al.employee_id = v_claim_before.employee_id
      and public.harmony_safe_date(al.attendance_date::text) = v_claim_before.phl_date
      and coalesce(al.is_locked, false) = true
      and al.deleted_at is null
  ) then
    raise exception 'Absensi pada tanggal klaim sudah dikunci HR. Buka lock terlebih dahulu.';
  end if;

  if exists (
    select 1
    from public.phl_claim_allocations pca
    where pca.claim_record_id = v_claim_before.id
      and pca.reversed_at is null
  ) then
    raise exception 'Klaim sudah memiliki alokasi aktif. Proses dihentikan untuk mencegah pemotongan ganda.';
  end if;

  -- Kunci semua saldo sumber yang dapat digunakan.
  perform pr.id
  from public.phl_records pr
  where pr.employee_id = v_claim_before.employee_id
    and lower(coalesce(pr.source, '')) = 'attendance_phl_approved'
    and lower(coalesce(pr.status, '')) = 'approved'
    and coalesce(pr.remaining_days, 0) > 0
    and (
      pr.expired_at is null
      or pr.expired_at >= current_date
    )
  order by
    pr.expired_at asc nulls last,
    pr.valid_from asc nulls last,
    pr.created_at asc nulls last,
    pr.id
  for update;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'source_record_id', pr.id,
        'balance_days', coalesce(pr.balance_days, 0),
        'used_before', coalesce(pr.used_days, 0),
        'remaining_before', coalesce(pr.remaining_days, 0),
        'valid_from', pr.valid_from,
        'expired_at', pr.expired_at
      )
      order by
        pr.expired_at asc nulls last,
        pr.valid_from asc nulls last,
        pr.created_at asc nulls last,
        pr.id
    ),
    '[]'::jsonb
  ),
  coalesce(sum(coalesce(pr.remaining_days, 0)), 0)
  into
    v_source_snapshot,
    v_available_before
  from public.phl_records pr
  where pr.employee_id = v_claim_before.employee_id
    and lower(coalesce(pr.source, '')) = 'attendance_phl_approved'
    and lower(coalesce(pr.status, '')) = 'approved'
    and coalesce(pr.remaining_days, 0) > 0
    and (
      pr.expired_at is null
      or pr.expired_at >= current_date
    );

  select *
  into v_employee
  from public.employees
  where id = v_claim_before.employee_id
  for update;

  if found then
    v_override_before := v_employee.phl_balance;
  end if;

  select public.approve_phl_claim(
    p_claim_record_id => v_claim_before.id,
    p_approved_by => v_approved_by
  )::text
  into v_legacy_message;

  update public.phl_records
  set
    hr_note = v_approval_note,
    hr_cancelled_by = null,
    hr_cancelled_at = null,
    hr_cancel_note = null,
    updated_at = now()
  where id = v_claim_before.id;

  select *
  into v_claim_after
  from public.phl_records
  where id = v_claim_before.id;

  if not found then
    raise exception 'Klaim PHL hilang setelah proses approval.';
  end if;

  if lower(coalesce(v_claim_after.status, '')) <> 'approved'
     and lower(coalesce(v_claim_after.hr_status, '')) <> 'approved' then
    raise exception
      'Engine approval PHL tidak menghasilkan status approved. Pesan engine: %',
      coalesce(v_legacy_message, '-');
  end if;

  -- Bandingkan saldo sumber sebelum dan sesudah engine lama.
  for v_snapshot_item in
    select value
    from jsonb_array_elements(v_source_snapshot)
  loop
    v_source_id := (v_snapshot_item ->> 'source_record_id')::uuid;
    v_source_balance := coalesce((v_snapshot_item ->> 'balance_days')::numeric, 0);
    v_source_used_before := coalesce((v_snapshot_item ->> 'used_before')::numeric, 0);
    v_source_remaining_before := coalesce((v_snapshot_item ->> 'remaining_before')::numeric, 0);
    v_source_valid_from := nullif(v_snapshot_item ->> 'valid_from', '')::date;
    v_source_expired_at := nullif(v_snapshot_item ->> 'expired_at', '')::date;

    select
      coalesce(pr.used_days, 0),
      coalesce(pr.remaining_days, 0)
    into
      v_source_used_after,
      v_source_remaining_after
    from public.phl_records pr
    where pr.id = v_source_id;

    if not found then
      raise exception 'Saldo PHL sumber % tidak ditemukan setelah approval.', v_source_id;
    end if;

    v_consumed := greatest(
      v_source_remaining_before - v_source_remaining_after,
      0
    );

    if v_consumed > 0 then
      insert into public.phl_claim_allocations (
        claim_record_id,
        source_record_id,
        employee_id,
        allocated_days,
        source_balance_days,
        source_used_before,
        source_used_after,
        source_remaining_before,
        source_remaining_after,
        source_valid_from,
        source_expired_at,
        allocated_by,
        allocated_by_email,
        metadata
      )
      values (
        v_claim_before.id,
        v_source_id,
        v_claim_before.employee_id,
        v_consumed,
        v_source_balance,
        v_source_used_before,
        v_source_used_after,
        v_source_remaining_before,
        v_source_remaining_after,
        v_source_valid_from,
        v_source_expired_at,
        auth.uid(),
        v_approved_by,
        jsonb_build_object(
          'capture_method', 'before_after_snapshot',
          'balance_engine', 'legacy_approve_phl_claim'
        )
      )
      on conflict (claim_record_id, source_record_id)
      do update set
        allocated_days = excluded.allocated_days,
        source_balance_days = excluded.source_balance_days,
        source_used_before = excluded.source_used_before,
        source_used_after = excluded.source_used_after,
        source_remaining_before = excluded.source_remaining_before,
        source_remaining_after = excluded.source_remaining_after,
        source_valid_from = excluded.source_valid_from,
        source_expired_at = excluded.source_expired_at,
        allocated_by = excluded.allocated_by,
        allocated_by_email = excluded.allocated_by_email,
        allocated_at = now(),
        reversed_by = null,
        reversed_by_email = null,
        reversed_at = null,
        reversal_note = null,
        metadata = excluded.metadata;

      v_allocated_total := v_allocated_total + v_consumed;
      v_allocation_count := v_allocation_count + 1;
    end if;
  end loop;

  select coalesce(sum(coalesce(pr.remaining_days, 0)), 0)
  into v_available_after
  from public.phl_records pr
  where pr.employee_id = v_claim_before.employee_id
    and lower(coalesce(pr.source, '')) = 'attendance_phl_approved'
    and lower(coalesce(pr.status, '')) = 'approved'
    and coalesce(pr.remaining_days, 0) > 0
    and (
      pr.expired_at is null
      or pr.expired_at >= current_date
    );

  select e.phl_balance
  into v_override_after
  from public.employees e
  where e.id = v_claim_before.employee_id;

  if v_override_before is not null and v_override_after is not null then
    v_override_consumed := greatest(v_override_before - v_override_after, 0);

    -- BUG-009: employees.phl_balance is an effective-balance mirror.
    -- The mirror delta after FIFO consumption is NOT a second/manual debit.
    -- Null audit override values also keep future reversal FIFO-only.
    v_override_before := null;
    v_override_after := null;
    v_override_consumed := 0;
  end if;

  -- Approval hanya diterima bila setiap hari yang dipotong dapat dilacak.
  if abs((v_allocated_total + v_override_consumed) - v_claim_days) > 0.0001 then
    raise exception
      'Pemotongan saldo PHL tidak dapat dilacak penuh. Klaim: % hari, alokasi FIFO: % hari, saldo manual: % hari. Seluruh proses dibatalkan.',
      v_claim_days,
      v_allocated_total,
      v_override_consumed;
  end if;

  insert into public.phl_claim_audit_logs (
    claim_record_id,
    employee_id,
    employee_number,
    full_name,
    action,
    claim_days,
    source,
    status_before,
    status_after,
    hr_status_before,
    hr_status_after,
    available_balance_before,
    available_balance_after,
    employee_override_before,
    employee_override_after,
    actor_user_id,
    actor_email,
    note,
    legacy_message,
    metadata
  )
  values (
    v_claim_before.id,
    v_claim_before.employee_id,
    v_claim_before.employee_number,
    v_claim_before.full_name,
    'hr_approved',
    v_claim_days,
    v_claim_before.source,
    v_claim_before.status,
    v_claim_after.status,
    v_claim_before.hr_status,
    v_claim_after.hr_status,
    v_available_before,
    v_available_after,
    v_override_before,
    v_override_after,
    auth.uid(),
    v_approved_by,
    v_approval_note,
    v_legacy_message,
    jsonb_build_object(
      'phl_date', v_claim_before.phl_date,
      'supervisor_status', v_claim_before.supervisor_status,
      'balance_engine', 'legacy_approve_phl_claim',
      'allocation_count', v_allocation_count,
      'allocated_fifo_days', v_allocated_total,
      'employee_override_consumed', v_override_consumed,
      'reversal_ready', true
    )
  );

  return jsonb_build_object(
    'success', true,
    'already_approved', false,
    'claim_record_id', v_claim_after.id,
    'employee_id', v_claim_after.employee_id,
    'claim_days', v_claim_days,
    'available_balance_before', v_available_before,
    'available_balance_after', v_available_after,
    'employee_override_before', v_override_before,
    'employee_override_after', v_override_after,
    'allocated_fifo_days', v_allocated_total,
    'employee_override_consumed', v_override_consumed,
    'allocation_count', v_allocation_count,
    'legacy_message', v_legacy_message,
    'message', 'Klaim PHL berhasil disetujui, alokasi FIFO tercatat, dan reversal siap digunakan.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.hr_cancel_approved_leave_request_atomic(p_request_id uuid, p_cancelled_by text DEFAULT NULL::text, p_note text DEFAULT 'Dibatalkan oleh HR.'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_request public.leave_requests%rowtype;
  v_employee public.employees%rowtype;
  v_approval_audit public.leave_balance_audit_logs%rowtype;
  v_existing_cancel_audit public.leave_balance_audit_logs%rowtype;

  v_actor_role text;
  v_actor_email text;
  v_cancelled_by text;
  v_cancel_note text;

  v_balance_field text := null;
  v_balance_before numeric(10, 2) := null;
  v_balance_after numeric(10, 2) := null;
  v_restore_days numeric(10, 2) := 0;
begin
  if auth.uid() is null then
    raise exception 'Sesi login tidak ditemukan. Silakan login ulang.';
  end if;

  select
    lower(coalesce(au.role, '')),
    lower(coalesce(au.email, ''))
  into
    v_actor_role,
    v_actor_email
  from public.app_users au
  where au.id = auth.uid()
    and coalesce(au.is_active, true) = true
  limit 1;

  if not (
    coalesce(v_actor_role, '') like '%hr%'
    or coalesce(v_actor_role, '') like '%admin%'
  ) then
    raise exception 'Hanya akun HR/Admin aktif yang dapat membatalkan pengajuan approved.';
  end if;

  v_cancelled_by := coalesce(
    nullif(btrim(coalesce(p_cancelled_by, '')), ''),
    nullif(v_actor_email, ''),
    'HR Administrator'
  );

  v_cancel_note := coalesce(
    nullif(btrim(coalesce(p_note, '')), ''),
    'Dibatalkan oleh HR.'
  );

  if length(v_cancel_note) < 5 then
    raise exception 'Alasan pembatalan minimal 5 karakter.';
  end if;

  -- Kunci pengajuan agar tidak diproses oleh dua aksi bersamaan.
  select *
  into v_request
  from public.leave_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'Pengajuan cuti/izin tidak ditemukan.';
  end if;

  -- Idempotent: klik ulang tidak mengembalikan saldo dua kali.
  if lower(coalesce(v_request.hr_status, '')) in ('cancelled', 'canceled')
     or lower(coalesce(v_request.status, '')) in ('cancelled', 'canceled') then
    return jsonb_build_object(
      'success', true,
      'already_cancelled', true,
      'request_id', v_request.id,
      'employee_id', v_request.employee_id,
      'message', 'Pengajuan sebelumnya sudah dibatalkan. Saldo tidak dikembalikan ulang.'
    );
  end if;

  if lower(coalesce(v_request.hr_status, '')) <> 'approved'
     and lower(coalesce(v_request.status, '')) <> 'approved' then
    raise exception 'Hanya pengajuan yang sudah approved HR yang dapat dibatalkan.';
  end if;

  if v_request.employee_id is null then
    raise exception 'Pengajuan belum terhubung ke data employee.';
  end if;

  if v_request.start_date is null or v_request.end_date is null then
    raise exception 'Tanggal mulai atau tanggal selesai pengajuan belum lengkap.';
  end if;

  -- Periode locked tidak boleh diubah diam-diam.
  if exists (
    select 1
    from public.attendance_period_confirmations apc
    where apc.employee_id = v_request.employee_id
      and coalesce(apc.is_locked, false) = true
      and apc.period_start <= v_request.end_date
      and apc.period_end >= v_request.start_date
  ) then
    raise exception 'Periode absensi terkait sudah dikunci HR. Buka lock terlebih dahulu sebelum membatalkan pengajuan.';
  end if;

  if exists (
    select 1
    from public.attendance_logs al
    where al.employee_id = v_request.employee_id
      and public.harmony_safe_date(al.attendance_date::text) between v_request.start_date and v_request.end_date
      and coalesce(al.is_locked, false) = true
      and al.deleted_at is null
  ) then
    raise exception 'Salah satu tanggal absensi terkait sudah dikunci HR. Buka lock terlebih dahulu.';
  end if;

  -- Cegah pengembalian saldo ganda bila status pernah diubah manual.
  select *
  into v_existing_cancel_audit
  from public.leave_balance_audit_logs
  where request_id = v_request.id
    and action = 'hr_cancelled'
  order by created_at desc
  limit 1;

  if found then
    raise exception 'Audit pembatalan sudah ditemukan. Status request perlu diperiksa sebelum diproses ulang.';
  end if;

  -- Ambil audit approval terbaru. Nilai selisih audit adalah sumber kebenaran
  -- untuk jumlah saldo yang benar-benar pernah dipotong.
  select *
  into v_approval_audit
  from public.leave_balance_audit_logs
  where request_id = v_request.id
    and action = 'hr_approved'
  order by created_at desc
  limit 1;

  -- Kunci employee untuk menjaga saldo konsisten.
  select *
  into v_employee
  from public.employees
  where id = v_request.employee_id
  for update;

  if not found then
    raise exception 'Data employee untuk pengajuan ini tidak ditemukan.';
  end if;

  if v_approval_audit.id is not null
     and v_approval_audit.balance_field in ('annual_leave_balance', 'phl_balance')
     and v_approval_audit.balance_before is not null
     and v_approval_audit.balance_after is not null then

    v_balance_field := v_approval_audit.balance_field;
    v_restore_days := greatest(
      v_approval_audit.balance_before - v_approval_audit.balance_after,
      0
    );

    if v_restore_days > 0 then
      if v_balance_field = 'annual_leave_balance' then
        if v_employee.annual_leave_balance is null then
          raise exception 'Saldo cuti manual saat ini sudah dinonaktifkan. Aktifkan atau sesuaikan saldo manual terlebih dahulu sebelum pembatalan.';
        end if;

        v_balance_before := v_employee.annual_leave_balance;
        v_balance_after := v_balance_before + v_restore_days;

        update public.employees
        set
          annual_leave_balance = v_balance_after,
          updated_at = now()
        where id = v_employee.id;

      elsif v_balance_field = 'phl_balance' then
        if v_employee.phl_balance is null then
          raise exception 'Saldo PHL manual saat ini sudah dinonaktifkan. Aktifkan atau sesuaikan saldo manual terlebih dahulu sebelum pembatalan.';
        end if;

        v_balance_before := v_employee.phl_balance;
        v_balance_after := v_balance_before + v_restore_days;

        update public.employees
        set
          phl_balance = v_balance_after,
          updated_at = now()
        where id = v_employee.id;
      end if;
    end if;
  end if;

  update public.leave_requests
  set
    status = 'cancelled',
    hr_status = 'cancelled',
    hr_cancelled_by = v_cancelled_by,
    hr_cancelled_at = now(),
    hr_cancel_note = v_cancel_note,
    updated_at = now()
  where id = v_request.id;

  -- Function sinkron harus membaca ulang status leave_requests.
  -- Request cancelled tidak lagi boleh menjadi absence aktif pada attendance_logs.
  perform public.sync_employee_absence_requests_to_attendance(
    v_request.employee_id,
    v_request.start_date,
    v_request.end_date
  );

  insert into public.leave_balance_audit_logs (
    request_id,
    employee_id,
    request_type,
    leave_type,
    total_days,
    balance_field,
    balance_before,
    balance_after,
    action,
    actor_user_id,
    actor_email,
    note,
    metadata
  )
  values (
    v_request.id,
    v_request.employee_id,
    v_request.request_type,
    v_request.leave_type,
    greatest(coalesce(v_request.total_days, 0), 0),
    v_balance_field,
    v_balance_before,
    v_balance_after,
    'hr_cancelled',
    auth.uid(),
    v_cancelled_by,
    v_cancel_note,
    jsonb_build_object(
      'period_start', v_request.start_date,
      'period_end', v_request.end_date,
      'attendance_sync', 'success',
      'approval_audit_id', v_approval_audit.id,
      'restored_days', v_restore_days,
      'manual_balance_restored', v_balance_field is not null and v_restore_days > 0
    )
  );

  return jsonb_build_object(
    'success', true,
    'already_cancelled', false,
    'request_id', v_request.id,
    'employee_id', v_request.employee_id,
    'balance_field', v_balance_field,
    'balance_before', v_balance_before,
    'balance_after', v_balance_after,
    'restored_days', v_restore_days,
    'attendance_sync', 'success',
    'message', 'Pengajuan approved berhasil dibatalkan, saldo dikembalikan sesuai audit, dan absensi disinkronkan ulang.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.hr_cancel_approved_phl_claim_atomic(p_claim_record_id uuid, p_cancelled_by text DEFAULT NULL::text, p_note text DEFAULT 'Dibatalkan oleh HR.'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_claim_before public.phl_records%rowtype;
  v_claim_after public.phl_records%rowtype;
  v_source public.phl_records%rowtype;
  v_allocation public.phl_claim_allocations%rowtype;

  v_actor_role text;
  v_actor_email text;
  v_cancelled_by text;
  v_cancel_note text;

  v_claim_days numeric(10, 2) := 0;
  v_allocation_total numeric(10, 2) := 0;
  v_override_before_approval numeric(10, 2) := null;
  v_override_after_approval numeric(10, 2) := null;
  v_override_restore numeric(10, 2) := 0;
  v_employee_override_before_cancel numeric(10, 2) := null;
  v_employee_override_after_cancel numeric(10, 2) := null;

  v_available_before numeric(10, 2) := 0;
  v_available_after numeric(10, 2) := 0;
  v_restored_fifo_days numeric(10, 2) := 0;
  v_restored_active_days numeric(10, 2) := 0;
  v_restored_expired_days numeric(10, 2) := 0;
  v_allocation_count integer := 0;
  v_next_used numeric(10, 2);
  v_next_remaining numeric(10, 2);
begin
  if auth.uid() is null then
    raise exception 'Sesi login tidak ditemukan. Silakan login ulang.';
  end if;

  select
    lower(coalesce(au.role, '')),
    lower(coalesce(au.email, ''))
  into
    v_actor_role,
    v_actor_email
  from public.app_users au
  where au.id = auth.uid()
    and coalesce(au.is_active, true) = true
  limit 1;

  if not (
    coalesce(v_actor_role, '') like '%hr%'
    or coalesce(v_actor_role, '') like '%admin%'
  ) then
    raise exception 'Hanya akun HR/Admin aktif yang dapat membatalkan klaim PHL.';
  end if;

  v_cancelled_by := coalesce(
    nullif(btrim(coalesce(p_cancelled_by, '')), ''),
    nullif(v_actor_email, ''),
    'HR Administrator'
  );

  v_cancel_note := coalesce(
    nullif(btrim(coalesce(p_note, '')), ''),
    'Dibatalkan oleh HR.'
  );

  if length(v_cancel_note) < 5 then
    raise exception 'Alasan pembatalan minimal 5 karakter.';
  end if;

  select *
  into v_claim_before
  from public.phl_records
  where id = p_claim_record_id
  for update;

  if not found then
    raise exception 'Data klaim PHL tidak ditemukan.';
  end if;

  if lower(coalesce(v_claim_before.source, '')) <> 'employee_phl_claim' then
    raise exception 'Record ini bukan klaim PHL karyawan.';
  end if;

  if lower(coalesce(v_claim_before.status, '')) in ('cancelled', 'canceled')
     or lower(coalesce(v_claim_before.hr_status, '')) in ('cancelled', 'canceled') then
    return jsonb_build_object(
      'success', true,
      'already_cancelled', true,
      'claim_record_id', v_claim_before.id,
      'employee_id', v_claim_before.employee_id,
      'message', 'Klaim PHL sebelumnya sudah dibatalkan. Saldo tidak dikembalikan ulang.'
    );
  end if;

  if lower(coalesce(v_claim_before.status, '')) <> 'approved'
     and lower(coalesce(v_claim_before.hr_status, '')) <> 'approved' then
    raise exception 'Hanya klaim PHL yang sudah approved yang dapat dibatalkan.';
  end if;

  if exists (
    select 1
    from public.phl_claim_audit_logs pcal
    where pcal.claim_record_id = v_claim_before.id
      and pcal.action = 'hr_cancelled'
  ) then
    raise exception 'Audit pembatalan klaim sudah tersedia. Reversal kedua diblokir.';
  end if;

  if v_claim_before.employee_id is null then
    raise exception 'Klaim PHL belum terhubung ke data employee.';
  end if;

  if v_claim_before.phl_date is null then
    raise exception 'Tanggal klaim PHL belum tersedia.';
  end if;

  if exists (
    select 1
    from public.attendance_period_confirmations apc
    where apc.employee_id = v_claim_before.employee_id
      and coalesce(apc.is_locked, false) = true
      and apc.period_start <= v_claim_before.phl_date
      and apc.period_end >= v_claim_before.phl_date
  ) then
    raise exception 'Periode absensi tanggal klaim sudah dikunci HR. Buka lock terlebih dahulu.';
  end if;

  if exists (
    select 1
    from public.attendance_logs al
    where al.employee_id = v_claim_before.employee_id
      and public.harmony_safe_date(al.attendance_date::text) = v_claim_before.phl_date
      and coalesce(al.is_locked, false) = true
      and al.deleted_at is null
  ) then
    raise exception 'Absensi pada tanggal klaim sudah dikunci HR. Buka lock terlebih dahulu.';
  end if;

  v_claim_days := coalesce(
    nullif(v_claim_before.used_days, 0),
    nullif(v_claim_before.balance_days, 0),
    0
  );

  select
    coalesce(sum(pca.allocated_days), 0),
    count(*)::integer
  into
    v_allocation_total,
    v_allocation_count
  from public.phl_claim_allocations pca
  where pca.claim_record_id = v_claim_before.id
    and pca.reversed_at is null;

  select
    pcal.employee_override_before,
    pcal.employee_override_after
  into
    v_override_before_approval,
    v_override_after_approval
  from public.phl_claim_audit_logs pcal
  where pcal.claim_record_id = v_claim_before.id
    and pcal.action = 'hr_approved'
  order by pcal.created_at desc
  limit 1;

  if v_override_before_approval is not null
     and v_override_after_approval is not null then
    v_override_restore := greatest(
      v_override_before_approval - v_override_after_approval,
      0
    );
  end if;

  if abs((v_allocation_total + v_override_restore) - v_claim_days) > 0.0001 then
    raise exception
      'Reversal aman tidak dapat dilakukan karena alokasi historis belum lengkap. Klaim: % hari, alokasi FIFO: % hari, saldo manual: % hari. Gunakan koreksi saldo manual dengan audit HR.',
      v_claim_days,
      v_allocation_total,
      v_override_restore;
  end if;

  select coalesce(sum(coalesce(pr.remaining_days, 0)), 0)
  into v_available_before
  from public.phl_records pr
  where pr.employee_id = v_claim_before.employee_id
    and lower(coalesce(pr.source, '')) = 'attendance_phl_approved'
    and lower(coalesce(pr.status, '')) = 'approved'
    and coalesce(pr.remaining_days, 0) > 0
    and (
      pr.expired_at is null
      or pr.expired_at >= current_date
    );

  -- Restore setiap alokasi ke saldo sumber aslinya.
  for v_allocation in
    select pca.*
    from public.phl_claim_allocations pca
    where pca.claim_record_id = v_claim_before.id
      and pca.reversed_at is null
    order by pca.allocated_at, pca.id
    for update
  loop
    select *
    into v_source
    from public.phl_records
    where id = v_allocation.source_record_id
    for update;

    if not found then
      raise exception
        'Saldo PHL sumber % tidak ditemukan. Reversal dibatalkan.',
        v_allocation.source_record_id;
    end if;

    if coalesce(v_source.used_days, 0) + 0.0001 < v_allocation.allocated_days then
      raise exception
        'Used days saldo sumber % lebih kecil dari alokasi reversal.',
        v_allocation.source_record_id;
    end if;

    v_next_used := greatest(
      coalesce(v_source.used_days, 0) - v_allocation.allocated_days,
      0
    );

    v_next_remaining :=
      coalesce(v_source.remaining_days, 0) + v_allocation.allocated_days;

    if v_source.balance_days is not null
       and v_next_remaining > v_source.balance_days + 0.0001 then
      raise exception
        'Reversal akan membuat sisa saldo sumber % melebihi total saldo.',
        v_allocation.source_record_id;
    end if;

    update public.phl_records
    set
      used_days = v_next_used,
      remaining_days = v_next_remaining,
      updated_at = now()
    where id = v_source.id;

    update public.phl_claim_allocations
    set
      reversed_by = auth.uid(),
      reversed_by_email = v_cancelled_by,
      reversed_at = now(),
      reversal_note = v_cancel_note
    where id = v_allocation.id;

    v_restored_fifo_days :=
      v_restored_fifo_days + v_allocation.allocated_days;

    if v_allocation.source_expired_at is not null
       and v_allocation.source_expired_at < current_date then
      v_restored_expired_days :=
        v_restored_expired_days + v_allocation.allocated_days;
    else
      v_restored_active_days :=
        v_restored_active_days + v_allocation.allocated_days;
    end if;
  end loop;

  -- Restore saldo manual employee bila approval sebelumnya memotong override.
  select e.phl_balance
  into v_employee_override_before_cancel
  from public.employees e
  where e.id = v_claim_before.employee_id
  for update;

  if v_override_restore > 0 then
    update public.employees
    set
      phl_balance = coalesce(phl_balance, 0) + v_override_restore,
      updated_at = now()
    where id = v_claim_before.employee_id;
  end if;

  select e.phl_balance
  into v_employee_override_after_cancel
  from public.employees e
  where e.id = v_claim_before.employee_id;

  update public.phl_records
  set
    status = 'cancelled',
    hr_status = 'cancelled',
    hr_cancelled_by = v_cancelled_by,
    hr_cancelled_at = now(),
    hr_cancel_note = v_cancel_note,
    hr_note = v_cancel_note,
    updated_at = now()
  where id = v_claim_before.id;

  select *
  into v_claim_after
  from public.phl_records
  where id = v_claim_before.id;

  select coalesce(sum(coalesce(pr.remaining_days, 0)), 0)
  into v_available_after
  from public.phl_records pr
  where pr.employee_id = v_claim_before.employee_id
    and lower(coalesce(pr.source, '')) = 'attendance_phl_approved'
    and lower(coalesce(pr.status, '')) = 'approved'
    and coalesce(pr.remaining_days, 0) > 0
    and (
      pr.expired_at is null
      or pr.expired_at >= current_date
    );

  insert into public.phl_claim_audit_logs (
    claim_record_id,
    employee_id,
    employee_number,
    full_name,
    action,
    claim_days,
    source,
    status_before,
    status_after,
    hr_status_before,
    hr_status_after,
    available_balance_before,
    available_balance_after,
    employee_override_before,
    employee_override_after,
    actor_user_id,
    actor_email,
    note,
    legacy_message,
    metadata
  )
  values (
    v_claim_before.id,
    v_claim_before.employee_id,
    v_claim_before.employee_number,
    v_claim_before.full_name,
    'hr_cancelled',
    v_claim_days,
    v_claim_before.source,
    v_claim_before.status,
    v_claim_after.status,
    v_claim_before.hr_status,
    v_claim_after.hr_status,
    v_available_before,
    v_available_after,
    v_employee_override_before_cancel,
    v_employee_override_after_cancel,
    auth.uid(),
    v_cancelled_by,
    v_cancel_note,
    null,
    jsonb_build_object(
      'phl_date', v_claim_before.phl_date,
      'allocation_count', v_allocation_count,
      'restored_fifo_days', v_restored_fifo_days,
      'restored_employee_override_days', v_override_restore,
      'restored_active_days', v_restored_active_days,
      'restored_expired_days', v_restored_expired_days,
      'original_expiry_preserved', true
    )
  );

  return jsonb_build_object(
    'success', true,
    'already_cancelled', false,
    'claim_record_id', v_claim_after.id,
    'employee_id', v_claim_after.employee_id,
    'claim_days', v_claim_days,
    'allocation_count', v_allocation_count,
    'restored_fifo_days', v_restored_fifo_days,
    'restored_employee_override_days', v_override_restore,
    'restored_active_days', v_restored_active_days,
    'restored_expired_days', v_restored_expired_days,
    'available_balance_before', v_available_before,
    'available_balance_after', v_available_after,
    'employee_override_before', v_employee_override_before_cancel,
    'employee_override_after', v_employee_override_after_cancel,
    'message', 'Klaim PHL berhasil dibatalkan dan saldo dikembalikan ke sumber FIFO asli.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.hr_mark_legacy_phl_claim_reviewed(p_claim_record_id uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_claim public.phl_records%rowtype;
  v_actor_role text;
  v_actor_email text;
  v_note text;

  v_claim_days numeric(10, 2) := 0;
  v_allocated_days numeric(10, 2) := 0;
  v_override_consumed numeric(10, 2) := 0;
  v_tracking_gap numeric(10, 2) := 0;
begin
  if auth.uid() is null then
    raise exception 'Sesi login tidak ditemukan. Silakan login ulang.';
  end if;

  select
    lower(coalesce(au.role, '')),
    lower(coalesce(au.email, ''))
  into
    v_actor_role,
    v_actor_email
  from public.app_users au
  where au.id = auth.uid()
    and coalesce(au.is_active, true) = true
  limit 1;

  if not (
    coalesce(v_actor_role, '') like '%hr%'
    or coalesce(v_actor_role, '') like '%admin%'
  ) then
    raise exception 'Hanya akun HR/Admin aktif yang dapat mereview klaim legacy.';
  end if;

  v_note := btrim(coalesce(p_note, ''));

  if length(v_note) < 5 then
    raise exception 'Catatan review minimal 5 karakter.';
  end if;

  select *
  into v_claim
  from public.phl_records
  where id = p_claim_record_id
  for update;

  if not found then
    raise exception 'Klaim PHL tidak ditemukan.';
  end if;

  if lower(coalesce(v_claim.source, '')) <> 'employee_phl_claim' then
    raise exception 'Record ini bukan klaim PHL karyawan.';
  end if;

  if lower(coalesce(v_claim.status, '')) <> 'approved'
     and lower(coalesce(v_claim.hr_status, '')) <> 'approved' then
    raise exception 'Hanya klaim PHL approved yang dapat ditandai sebagai legacy review.';
  end if;

  v_claim_days := coalesce(
    nullif(v_claim.used_days, 0),
    nullif(v_claim.balance_days, 0),
    0
  );

  select coalesce(sum(pca.allocated_days), 0)::numeric
  into v_allocated_days
  from public.phl_claim_allocations pca
  where pca.claim_record_id = v_claim.id
    and pca.reversed_at is null;

  select
    greatest(
      coalesce(pcal.employee_override_before, 0)
      -
      coalesce(pcal.employee_override_after, 0),
      0
    )::numeric
  into v_override_consumed
  from public.phl_claim_audit_logs pcal
  where pcal.claim_record_id = v_claim.id
    and pcal.action = 'hr_approved'
  order by pcal.created_at desc
  limit 1;

  v_override_consumed := coalesce(v_override_consumed, 0);

  v_tracking_gap := abs(
    v_claim_days
    -
    (
      v_allocated_days
      +
      v_override_consumed
    )
  );

  if v_tracking_gap <= 0.0001 then
    raise exception 'Klaim ini sudah memiliki tracking saldo lengkap dan tidak termasuk klaim legacy.';
  end if;

  update public.phl_records
  set
    legacy_review_status = 'reviewed',
    legacy_review_note = v_note,
    legacy_reviewed_by = coalesce(
      nullif(v_actor_email, ''),
      'HR Administrator'
    ),
    legacy_reviewed_at = now(),
    updated_at = now()
  where id = v_claim.id;

  insert into public.phl_reconciliation_audit_logs (
    employee_id,
    claim_record_id,
    employee_number,
    full_name,
    action,
    active_ledger_balance,
    expired_remaining_balance,
    manual_phl_balance,
    manual_ledger_difference,
    tracking_gap_days,
    legacy_gap_count,
    actor_user_id,
    actor_email,
    note,
    metadata
  )
  values (
    v_claim.employee_id,
    v_claim.id,
    v_claim.employee_number,
    v_claim.full_name,
    'legacy_claim_reviewed',
    null,
    null,
    null,
    null,
    v_tracking_gap,
    1,
    auth.uid(),
    coalesce(nullif(v_actor_email, ''), 'HR Administrator'),
    v_note,
    jsonb_build_object(
      'claim_days', v_claim_days,
      'allocated_days', v_allocated_days,
      'override_consumed_days', v_override_consumed,
      'automatic_reversal_available', false,
      'balance_changed', false
    )
  );

  return jsonb_build_object(
    'success', true,
    'claim_record_id', v_claim.id,
    'claim_days', v_claim_days,
    'allocated_days', v_allocated_days,
    'override_consumed_days', v_override_consumed,
    'tracking_gap_days', v_tracking_gap,
    'message', 'Klaim legacy berhasil ditandai sudah direview. Saldo tidak diubah.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.hr_reject_phl_claim_atomic(p_claim_record_id uuid, p_rejected_by text DEFAULT NULL::text, p_reason text DEFAULT 'Ditolak oleh HR.'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_claim_before public.phl_records%rowtype;
  v_claim_after public.phl_records%rowtype;

  v_actor_role text;
  v_actor_email text;
  v_rejected_by text;
  v_reject_reason text;
  v_legacy_message text;
  v_claim_days numeric(10, 2) := 0;
  v_available_balance numeric(10, 2) := 0;
  v_employee_override numeric(10, 2) := null;
begin
  if auth.uid() is null then
    raise exception 'Sesi login tidak ditemukan. Silakan login ulang.';
  end if;

  select
    lower(coalesce(au.role, '')),
    lower(coalesce(au.email, ''))
  into
    v_actor_role,
    v_actor_email
  from public.app_users au
  where au.id = auth.uid()
    and coalesce(au.is_active, true) = true
  limit 1;

  if not (
    coalesce(v_actor_role, '') like '%hr%'
    or coalesce(v_actor_role, '') like '%admin%'
  ) then
    raise exception 'Hanya akun HR/Admin aktif yang dapat menolak klaim PHL.';
  end if;

  v_rejected_by := coalesce(
    nullif(btrim(coalesce(p_rejected_by, '')), ''),
    nullif(v_actor_email, ''),
    'HR Administrator'
  );

  v_reject_reason := coalesce(
    nullif(btrim(coalesce(p_reason, '')), ''),
    'Ditolak oleh HR.'
  );

  if length(v_reject_reason) < 5 then
    raise exception 'Alasan penolakan minimal 5 karakter.';
  end if;

  select *
  into v_claim_before
  from public.phl_records
  where id = p_claim_record_id
  for update;

  if not found then
    raise exception 'Data klaim PHL tidak ditemukan.';
  end if;

  if lower(coalesce(v_claim_before.source, '')) <> 'employee_phl_claim' then
    raise exception 'Record ini bukan klaim PHL karyawan.';
  end if;

  if lower(coalesce(v_claim_before.status, '')) = 'rejected'
     or lower(coalesce(v_claim_before.hr_status, '')) = 'rejected' then
    return jsonb_build_object(
      'success', true,
      'already_rejected', true,
      'claim_record_id', v_claim_before.id,
      'employee_id', v_claim_before.employee_id,
      'message', 'Klaim PHL sebelumnya sudah ditolak.'
    );
  end if;

  if lower(coalesce(v_claim_before.status, '')) = 'approved'
     or lower(coalesce(v_claim_before.hr_status, '')) = 'approved' then
    raise exception 'Klaim PHL yang sudah approved tidak boleh langsung ditolak. Gunakan pembatalan.';
  end if;

  v_claim_days := coalesce(
    nullif(v_claim_before.used_days, 0),
    nullif(v_claim_before.balance_days, 0),
    0
  );

  select coalesce(sum(coalesce(pr.remaining_days, 0)), 0)
  into v_available_balance
  from public.phl_records pr
  where pr.employee_id = v_claim_before.employee_id
    and lower(coalesce(pr.source, '')) = 'attendance_phl_approved'
    and lower(coalesce(pr.status, '')) = 'approved'
    and coalesce(pr.remaining_days, 0) > 0
    and (
      pr.expired_at is null
      or pr.expired_at >= current_date
    );

  select e.phl_balance
  into v_employee_override
  from public.employees e
  where e.id = v_claim_before.employee_id;

  select public.reject_phl_claim(
    p_claim_record_id => v_claim_before.id,
    p_rejected_by => v_rejected_by,
    p_reason => v_reject_reason
  )::text
  into v_legacy_message;

  update public.phl_records
  set
    hr_note = v_reject_reason,
    updated_at = now()
  where id = v_claim_before.id;

  select *
  into v_claim_after
  from public.phl_records
  where id = v_claim_before.id;

  if not found then
    raise exception 'Klaim PHL hilang setelah proses penolakan.';
  end if;

  if lower(coalesce(v_claim_after.status, '')) <> 'rejected'
     and lower(coalesce(v_claim_after.hr_status, '')) <> 'rejected' then
    raise exception
      'Engine penolakan PHL tidak menghasilkan status rejected. Pesan engine: %',
      coalesce(v_legacy_message, '-');
  end if;

  insert into public.phl_claim_audit_logs (
    claim_record_id,
    employee_id,
    employee_number,
    full_name,
    action,
    claim_days,
    source,
    status_before,
    status_after,
    hr_status_before,
    hr_status_after,
    available_balance_before,
    available_balance_after,
    employee_override_before,
    employee_override_after,
    actor_user_id,
    actor_email,
    note,
    legacy_message,
    metadata
  )
  values (
    v_claim_before.id,
    v_claim_before.employee_id,
    v_claim_before.employee_number,
    v_claim_before.full_name,
    'hr_rejected',
    v_claim_days,
    v_claim_before.source,
    v_claim_before.status,
    v_claim_after.status,
    v_claim_before.hr_status,
    v_claim_after.hr_status,
    v_available_balance,
    v_available_balance,
    v_employee_override,
    v_employee_override,
    auth.uid(),
    v_rejected_by,
    v_reject_reason,
    v_legacy_message,
    jsonb_build_object(
      'phl_date', v_claim_before.phl_date,
      'supervisor_status', v_claim_before.supervisor_status,
      'balance_changed', false
    )
  );

  return jsonb_build_object(
    'success', true,
    'already_rejected', false,
    'claim_record_id', v_claim_after.id,
    'employee_id', v_claim_after.employee_id,
    'claim_days', v_claim_days,
    'legacy_message', v_legacy_message,
    'message', 'Klaim PHL berhasil ditolak secara atomik.'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.hr_set_harmony_request_type_active(p_code text, p_is_active boolean, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_code text := lower(btrim(coalesce(p_code, '')));
  v_row public.harmony_request_types%rowtype;
  v_actor text;
begin
  if not public.harmony_leave_is_active_hr_admin() then
    raise exception 'Hanya HR/Admin aktif yang dapat mengubah master jenis.';
  end if;

  select * into v_row
  from public.harmony_request_types
  where code = v_code
  for update;

  if not found then
    raise exception 'Jenis % tidak ditemukan.', v_code;
  end if;

  if coalesce(v_row.is_system, false)
     and v_code in ('present','manual_attendance','annual_leave','phl_claim')
     and not coalesce(p_is_active, false) then
    raise exception 'Jenis inti % tidak boleh dinonaktifkan karena dipakai oleh flow saldo/absensi.', v_row.label;
  end if;

  v_actor := coalesce(nullif(lower(auth.jwt() ->> 'email'), ''), 'HR Administrator');

  update public.harmony_request_types
  set
    is_active = coalesce(p_is_active, false),
    updated_by = v_actor,
    description = case
      when nullif(btrim(coalesce(p_note, '')), '') is null then description
      else concat_ws(E'\n', nullif(description, ''), '[ADMIN] ' || btrim(p_note))
    end,
    updated_at = now()
  where code = v_code;

  return jsonb_build_object(
    'success', true,
    'code', v_code,
    'is_active', coalesce(p_is_active, false),
    'message', case when coalesce(p_is_active, false)
      then 'Jenis berhasil diaktifkan kembali.'
      else 'Jenis dihapus dari dropdown. Histori lama tetap tersimpan.'
    end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.map_leave_request_to_attendance_status(p_request_type text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_type text;
begin
  v_type := lower(coalesce(p_request_type, ''));

  if v_type = 'sick' then
    return 'sick';
  end if;

  if v_type = 'permit' then
    return 'permit';
  end if;

  if v_type = 'official_travel' then
    return 'official_travel';
  end if;

  if v_type = 'phl_claim' then
    return 'phl_claim';
  end if;

  if v_type in (
    'annual_leave',
    'marriage_leave',
    'maternity_leave',
    'miscarriage_leave',
    'bereavement_leave',
    'child_circumcision_leave',
    'worship_leave',
    'menstrual_leave',
    'pregnancy_check_leave',
    'other_leave'
  ) then
    return 'leave';
  end if;

  return 'leave';
end;
$function$

CREATE OR REPLACE FUNCTION public.map_leave_request_to_label(p_request_type text, p_leave_type text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_type text;
begin
  if nullif(trim(coalesce(p_leave_type, '')), '') is not null then
    return p_leave_type;
  end if;

  v_type := lower(coalesce(p_request_type, ''));

  if v_type = 'annual_leave' then return 'Cuti Tahunan'; end if;
  if v_type = 'marriage_leave' then return 'Cuti Menikah'; end if;
  if v_type = 'maternity_leave' then return 'Cuti Melahirkan'; end if;
  if v_type = 'miscarriage_leave' then return 'Cuti Keguguran'; end if;
  if v_type = 'bereavement_leave' then return 'Cuti Duka'; end if;
  if v_type = 'child_circumcision_leave' then return 'Cuti Khitan / Baptis Anak'; end if;
  if v_type = 'worship_leave' then return 'Cuti Ibadah'; end if;
  if v_type = 'menstrual_leave' then return 'Cuti Haid'; end if;
  if v_type = 'pregnancy_check_leave' then return 'Pemeriksaan Kehamilan'; end if;
  if v_type = 'sick' then return 'Sakit'; end if;
  if v_type = 'permit' then return 'Izin'; end if;
  if v_type = 'official_travel' then return 'Tugas Luar / Dinas'; end if;
  if v_type = 'phl_claim' then return 'Klaim PHL'; end if;
  if v_type = 'other_leave' then return 'Cuti Lainnya'; end if;

  return 'Cuti / Izin';
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_phl_claim_when_period_locked()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_employee_id uuid;
  v_phl_date date;
  v_source text;
  v_locked boolean;
begin
  if tg_op = 'DELETE' then
    v_employee_id := old.employee_id;
    v_phl_date := old.phl_date::date;
    v_source := old.source;
  else
    v_employee_id := new.employee_id;
    v_phl_date := new.phl_date::date;
    v_source := new.source;
  end if;

  if coalesce(v_source, '') <> 'employee_phl_claim' then
    if tg_op = 'DELETE' then
      return old;
    end if;

    return new;
  end if;

  v_locked := is_employee_attendance_date_locked(
    v_employee_id,
    v_phl_date
  );

  if v_locked then
    raise exception
      'Periode klaim PHL ini sudah dikunci HR. Buka lock terlebih dahulu jika perlu revisi.';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_leave_request_by_supervisor(p_request_id uuid, p_supervisor_id uuid, p_supervisor_name text, p_note text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_request leave_requests%rowtype;
  v_locked boolean;
begin
  select *
  into v_request
  from leave_requests
  where id = p_request_id;

  if not found then
    raise exception 'Pengajuan tidak ditemukan.';
  end if;

  if nullif(trim(coalesce(p_note, '')), '') is null then
    raise exception 'Alasan reject wajib diisi.';
  end if;

  v_locked := is_employee_date_range_locked(
    v_request.employee_id,
    v_request.start_date::date,
    v_request.end_date::date
  );

  if v_locked then
    raise exception 'Periode pengajuan ini sudah dikunci HR. Buka lock terlebih dahulu jika perlu approval/revisi.';
  end if;

  if coalesce(v_request.supervisor_status, 'pending') = 'approved' then
    if coalesce(v_request.request_type, '') = 'annual_leave' then
      perform rollback_employee_annual_leave_usage(
        v_request.id,
        p_supervisor_name,
        'supervisor',
        'Rollback karena pengajuan direject atasan.'
      );
    end if;

    if coalesce(v_request.request_type, '') = 'phl_claim' then
      perform rollback_employee_phl_usage(
        v_request.id,
        p_supervisor_name,
        'supervisor',
        'Rollback karena klaim PHL direject atasan.'
      );
    end if;
  end if;

  update leave_requests
  set
    status = 'rejected',
    supervisor_status = 'rejected',
    supervisor_id = p_supervisor_id,
    supervisor_name = p_supervisor_name,
    supervisor_approved_at = null,
    supervisor_rejected_at = now(),
    supervisor_note = p_note,
    hr_status = coalesce(hr_status, 'pending'),
    updated_at = now()
  where id = p_request_id;

  return 'Pengajuan berhasil ditolak atasan.';
end;
$function$

CREATE OR REPLACE FUNCTION public.remed_cancel_claim_v1(p_claim_id uuid, p_actor_auth_user_id uuid, p_actor_email text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_claim public.remed_claims%rowtype;
  v_access public.remed_user_access%rowtype;
begin
  select * into v_claim from public.remed_claims where id=p_claim_id for update;
  if not found then raise exception 'Klaim tidak ditemukan.'; end if;
  if v_claim.status <> 'pending_hr' then raise exception 'Hanya klaim yang masih menunggu HR yang dapat dibatalkan.'; end if;

  if p_actor_auth_user_id is not null then
    select * into v_access from public.remed_user_access where auth_user_id=p_actor_auth_user_id and is_active;
    if not found or v_access.role <> 'employee' or v_access.employee_id <> v_claim.employee_id then raise exception 'Akses pembatalan ditolak.'; end if;
  end if;

  if v_claim.affects_entitlement then
    update public.remed_entitlements
      set reserved_amount=greatest(0,reserved_amount-v_claim.submitted_amount)
      where employee_id=v_claim.employee_id and period_year=extract(year from v_claim.treatment_date)::integer;
  end if;
  update public.remed_claims set status='cancelled' where id=v_claim.id;
  insert into public.remed_status_logs(claim_id,from_status,to_status,actor_auth_user_id,actor_email,actor_role,note)
  values(v_claim.id,'pending_hr','cancelled',p_actor_auth_user_id,p_actor_email,case when p_actor_auth_user_id is null then 'system' else 'employee' end,p_reason);
end;
$function$

CREATE OR REPLACE FUNCTION public.remed_finance_review_claim_v1(p_claim_id uuid, p_decision text, p_note text, p_actor_auth_user_id uuid, p_actor_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_claim public.remed_claims%rowtype;
begin
  if not exists(select 1 from public.remed_user_access where auth_user_id=p_actor_auth_user_id and role='finance' and is_active) then raise exception 'Akses Finance Re-Med ditolak.'; end if;
  select * into v_claim from public.remed_claims where id=p_claim_id for update;
  if not found then raise exception 'Klaim tidak ditemukan.'; end if;
  if v_claim.status <> 'pending_finance' then raise exception 'Klaim sudah tidak berada pada antrean Finance.'; end if;

  if lower(p_decision)='approve' then
    update public.remed_claims set status='waiting_payment', finance_note=p_note, finance_reviewed_by=p_actor_auth_user_id, finance_reviewed_at=now() where id=v_claim.id;
    insert into public.remed_status_logs(claim_id,from_status,to_status,actor_auth_user_id,actor_email,actor_role,note) values(v_claim.id,'pending_finance','waiting_payment',p_actor_auth_user_id,p_actor_email,'finance',p_note);
  elsif lower(p_decision)='reject' then
    update public.remed_entitlements set reserved_amount=greatest(0,reserved_amount-coalesce(v_claim.approved_amount,v_claim.submitted_amount)) where employee_id=v_claim.employee_id and period_year=extract(year from v_claim.treatment_date)::integer;
    update public.remed_claims set status='rejected_finance', finance_note=p_note, finance_reviewed_by=p_actor_auth_user_id, finance_reviewed_at=now() where id=v_claim.id;
    insert into public.remed_status_logs(claim_id,from_status,to_status,actor_auth_user_id,actor_email,actor_role,note) values(v_claim.id,'pending_finance','rejected_finance',p_actor_auth_user_id,p_actor_email,'finance',p_note);
  else raise exception 'Keputusan Finance tidak valid.'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.remed_hr_review_claim_v1(p_claim_id uuid, p_decision text, p_approved_amount numeric, p_note text, p_actor_auth_user_id uuid, p_actor_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_claim public.remed_claims%rowtype;
  v_ent public.remed_entitlements%rowtype;
begin
  if not exists(select 1 from public.remed_user_access where auth_user_id=p_actor_auth_user_id and role='hr' and is_active) then raise exception 'Akses HR Re-Med ditolak.'; end if;
  select * into v_claim from public.remed_claims where id=p_claim_id for update;
  if not found then raise exception 'Klaim tidak ditemukan.'; end if;
  if v_claim.status <> 'pending_hr' then raise exception 'Klaim sudah tidak berada pada antrean HR.'; end if;
  select * into v_ent from public.remed_entitlements where employee_id=v_claim.employee_id and period_year=extract(year from v_claim.treatment_date)::integer for update;

  if lower(p_decision)='approve' then
    if p_approved_amount is null or p_approved_amount <= 0 or p_approved_amount > v_claim.submitted_amount then raise exception 'Nominal approved HR tidak valid.'; end if;
    update public.remed_entitlements set reserved_amount=greatest(0,reserved_amount-v_claim.submitted_amount+p_approved_amount) where id=v_ent.id;
    update public.remed_claims set status='pending_finance', approved_amount=p_approved_amount, hr_note=p_note, hr_reviewed_by=p_actor_auth_user_id, hr_reviewed_at=now() where id=v_claim.id;
    insert into public.remed_status_logs(claim_id,from_status,to_status,actor_auth_user_id,actor_email,actor_role,note) values(v_claim.id,'pending_hr','pending_finance',p_actor_auth_user_id,p_actor_email,'hr',p_note);
  elsif lower(p_decision)='reject' then
    update public.remed_entitlements set reserved_amount=greatest(0,reserved_amount-v_claim.submitted_amount) where id=v_ent.id;
    update public.remed_claims set status='rejected_hr', hr_note=p_note, hr_reviewed_by=p_actor_auth_user_id, hr_reviewed_at=now() where id=v_claim.id;
    insert into public.remed_status_logs(claim_id,from_status,to_status,actor_auth_user_id,actor_email,actor_role,note) values(v_claim.id,'pending_hr','rejected_hr',p_actor_auth_user_id,p_actor_email,'hr',p_note);
  else raise exception 'Keputusan HR tidak valid.'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.remed_mark_claim_paid_v1(p_claim_id uuid, p_payment_date date, p_payment_reference text, p_payment_proof_path text, p_note text, p_actor_auth_user_id uuid, p_actor_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_claim public.remed_claims%rowtype;
  v_amount numeric;
begin
  if not exists(select 1 from public.remed_user_access where auth_user_id=p_actor_auth_user_id and role='finance' and is_active) then raise exception 'Akses Finance Re-Med ditolak.'; end if;
  select * into v_claim from public.remed_claims where id=p_claim_id for update;
  if not found then raise exception 'Klaim tidak ditemukan.'; end if;
  if v_claim.status <> 'waiting_payment' then raise exception 'Klaim belum berada pada tahap pembayaran.'; end if;
  v_amount := coalesce(v_claim.approved_amount,v_claim.submitted_amount);

  update public.remed_entitlements
    set reserved_amount=greatest(0,reserved_amount-v_amount), current_used=current_used+v_amount
    where employee_id=v_claim.employee_id and period_year=extract(year from v_claim.treatment_date)::integer;
  update public.remed_claims set status='paid', payment_date=p_payment_date, payment_reference=p_payment_reference, payment_proof_path=p_payment_proof_path, finance_note=coalesce(p_note,finance_note) where id=v_claim.id;
  insert into public.remed_payment_logs(claim_id,amount,payment_date,payment_reference,payment_proof_path,actor_auth_user_id,actor_email,note)
  values(v_claim.id,v_amount,p_payment_date,p_payment_reference,p_payment_proof_path,p_actor_auth_user_id,p_actor_email,p_note);
  insert into public.remed_status_logs(claim_id,from_status,to_status,actor_auth_user_id,actor_email,actor_role,note) values(v_claim.id,'waiting_payment','paid',p_actor_auth_user_id,p_actor_email,'finance',p_note);
end;
$function$

CREATE OR REPLACE FUNCTION public.remed_set_entitlement_v1(p_employee_id uuid, p_period_year integer, p_plafond_total numeric, p_note text, p_actor_auth_user_id uuid, p_actor_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_used numeric := 0;
begin
  if not exists(select 1 from public.remed_user_access where auth_user_id=p_actor_auth_user_id and role='hr' and is_active) then raise exception 'Akses HR Re-Med ditolak.'; end if;
  select coalesce(legacy_used,0)+coalesce(current_used,0)+coalesce(reserved_amount,0) into v_used from public.remed_entitlements where employee_id=p_employee_id and period_year=p_period_year;
  if found and p_plafond_total < v_used then raise exception 'Plafond tidak boleh lebih kecil dari nilai yang sudah terpakai/terreservasi.'; end if;
  insert into public.remed_entitlements(employee_id,period_year,plafond_total,note) values(p_employee_id,p_period_year,p_plafond_total,p_note)
  on conflict(employee_id,period_year) do update set plafond_total=excluded.plafond_total, note=excluded.note;
  insert into public.remed_audit_logs(actor_auth_user_id,actor_email,actor_role,action,entity_type,entity_id,metadata)
  values(p_actor_auth_user_id,p_actor_email,'hr','entitlement_updated','employee',p_employee_id,jsonb_build_object('year',p_period_year,'plafond_total',p_plafond_total,'note',p_note));
end;
$function$

CREATE OR REPLACE FUNCTION public.remed_submit_claim_v1(p_employee_id uuid, p_claim_type_id uuid, p_treatment_date date, p_provider_name text, p_submitted_amount numeric, p_employee_note text, p_bank_name text, p_bank_account_number text, p_bank_account_name text, p_actor_auth_user_id uuid, p_actor_email text)
 RETURNS TABLE(claim_id uuid, claim_number text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ent public.remed_entitlements%rowtype;
  v_claim_id uuid;
  v_claim_number text;
  v_available numeric;
  v_year integer := extract(year from p_treatment_date)::integer;
begin
  if p_submitted_amount is null or p_submitted_amount <= 0 then raise exception 'Nominal klaim harus lebih dari 0.'; end if;
  if not exists(select 1 from public.remed_user_access a where a.auth_user_id=p_actor_auth_user_id and a.employee_id=p_employee_id and a.role='employee' and a.is_active) then
    raise exception 'Akun employee tidak berhak membuat klaim untuk employee ini.';
  end if;
  if not exists(select 1 from public.remed_claim_types t where t.id=p_claim_type_id and t.is_active) then raise exception 'Jenis klaim tidak aktif.'; end if;

  select * into v_ent from public.remed_entitlements where employee_id=p_employee_id and period_year=v_year for update;
  if not found then raise exception 'Plafond tahun % belum diatur oleh HR.', v_year; end if;
  v_available := v_ent.plafond_total-v_ent.legacy_used-v_ent.current_used-v_ent.reserved_amount;
  if p_submitted_amount > v_available then raise exception 'Nominal melebihi sisa plafond tersedia.'; end if;

  v_claim_number := public.remed_next_claim_number();
  insert into public.remed_claims(claim_number,employee_id,claim_type_id,treatment_date,provider_name,submitted_amount,employee_note,status,bank_name,bank_account_number,bank_account_name)
  values(v_claim_number,p_employee_id,p_claim_type_id,p_treatment_date,nullif(trim(p_provider_name),''),p_submitted_amount,nullif(trim(p_employee_note),''),'pending_hr',trim(p_bank_name),trim(p_bank_account_number),trim(p_bank_account_name))
  returning id into v_claim_id;

  update public.remed_entitlements set reserved_amount=reserved_amount+p_submitted_amount where id=v_ent.id;
  insert into public.remed_status_logs(claim_id,from_status,to_status,actor_auth_user_id,actor_email,actor_role,note)
  values(v_claim_id,null,'pending_hr',p_actor_auth_user_id,p_actor_email,'employee','Pengajuan reimbursement dibuat.');
  insert into public.remed_audit_logs(actor_auth_user_id,actor_email,actor_role,action,entity_type,entity_id,metadata)
  values(p_actor_auth_user_id,p_actor_email,'employee','claim_submitted','remed_claim',v_claim_id,jsonb_build_object('amount',p_submitted_amount));

  return query select v_claim_id, v_claim_number;
end;
$function$

CREATE OR REPLACE FUNCTION public.remed_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.supervisor_approve_phl_claim(p_claim_record_id uuid, p_approved_by text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_claim record;
begin
  select *
  into v_claim
  from phl_records
  where id = p_claim_record_id
  for update;

  if not found then
    return 'Klaim PHL tidak ditemukan.';
  end if;

  if coalesce(v_claim.source, '') <> 'employee_phl_claim' then
    return 'Record ini bukan pengajuan klaim PHL.';
  end if;

  if coalesce(v_claim.supervisor_status, 'pending') = 'approved' then
    return 'Klaim PHL ini sudah disetujui atasan.';
  end if;

  if coalesce(v_claim.supervisor_status, 'pending') = 'rejected' then
    return 'Klaim PHL ini sudah ditolak atasan.';
  end if;

  update phl_records
  set
    supervisor_status = 'approved',
    supervisor_approved_by = p_approved_by,
    supervisor_approved_at = now(),
    supervisor_note = p_note,
    hr_status = 'waiting_hr',
    status = 'waiting_hr',
    updated_at = now()
  where id = p_claim_record_id;

  return 'Klaim PHL berhasil disetujui atasan dan menunggu approval HR.';
end;
$function$

CREATE OR REPLACE FUNCTION public.supervisor_reject_phl_claim(p_claim_record_id uuid, p_rejected_by text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_claim record;
begin
  select *
  into v_claim
  from phl_records
  where id = p_claim_record_id
  for update;

  if not found then
    return 'Klaim PHL tidak ditemukan.';
  end if;

  if coalesce(v_claim.source, '') <> 'employee_phl_claim' then
    return 'Record ini bukan pengajuan klaim PHL.';
  end if;

  if coalesce(v_claim.supervisor_status, 'pending') = 'approved' then
    return 'Klaim PHL sudah disetujui atasan, tidak bisa ditolak.';
  end if;

  update phl_records
  set
    supervisor_status = 'rejected',
    supervisor_rejected_by = p_rejected_by,
    supervisor_rejected_at = now(),
    supervisor_note = p_note,
    hr_status = 'rejected_by_supervisor',
    status = 'rejected',
    updated_at = now()
  where id = p_claim_record_id;

  return 'Klaim PHL berhasil ditolak atasan.';
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_employee_absence_requests_to_attendance(p_employee_id uuid, p_period_start date, p_period_end date)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_message_1 text;
  v_message_2 text;
begin
  select sync_approved_leave_requests_to_attendance(
    p_employee_id,
    p_period_start,
    p_period_end
  )
  into v_message_1;

  select sync_approved_phl_claims_to_attendance(
    p_employee_id,
    p_period_start,
    p_period_end
  )
  into v_message_2;

  return v_message_1 || ' ' || v_message_2;
end;
$function$

CREATE OR REPLACE FUNCTION public.use_employee_phl_balance(p_employee_id uuid, p_leave_request_id uuid, p_days numeric, p_actor_name text DEFAULT 'System'::text, p_actor_role text DEFAULT 'system'::text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  r record;
  v_total_available numeric;
  v_remaining_need numeric;
  v_use_days numeric;
  v_before numeric;
  v_after numeric;
begin
  if p_days <= 0 then
    return 'Jumlah hari klaim PHL tidak valid.';
  end if;

  if exists (
    select 1
    from employee_phl_usage_transactions
    where leave_request_id = p_leave_request_id
      and transaction_type = 'use'
  ) then
    return 'Saldo PHL sudah pernah dikurangi untuk pengajuan ini.';
  end if;

  select coalesce(sum(remaining_days), 0)
  into v_total_available
  from phl_records
  where employee_id = p_employee_id
    and status = 'approved'
    and coalesce(remaining_days, 0) > 0
    and expired_at::date >= current_date;

  if v_total_available < p_days then
    return 'Saldo PHL tidak cukup. Sisa saldo: ' || v_total_available || ' hari.';
  end if;

  v_remaining_need := p_days;

  for r in
    select *
    from phl_records
    where employee_id = p_employee_id
      and status = 'approved'
      and coalesce(remaining_days, 0) > 0
      and expired_at::date >= current_date
    order by expired_at asc, phl_date asc
  loop
    exit when v_remaining_need <= 0;

    v_before := coalesce(r.remaining_days, 0);
    v_use_days := least(v_before, v_remaining_need);
    v_after := v_before - v_use_days;

    update phl_records
    set
      used_days = coalesce(used_days, 0) + v_use_days,
      remaining_days = v_after,
      updated_at = now()
    where id = r.id;

    insert into employee_phl_usage_transactions (
      phl_record_id,
      employee_id,
      leave_request_id,
      transaction_type,
      transaction_label,
      transaction_days,
      before_balance,
      after_balance,
      actor_name,
      actor_role,
      notes,
      created_at
    )
    values (
      r.id,
      p_employee_id,
      p_leave_request_id,
      'use',
      'Pemakaian Saldo PHL',
      v_use_days,
      v_before,
      v_after,
      p_actor_name,
      p_actor_role,
      coalesce(p_note, 'Saldo PHL digunakan dari approval klaim PHL.'),
      now()
    );

    v_remaining_need := v_remaining_need - v_use_days;
  end loop;

  return 'Saldo PHL berhasil dikurangi. Total dipakai: ' || p_days || ' hari.';
end;
$function$
